local LOTUS_LOGO_ID
do
    local function b64decode(data)
        local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for i = 1, 64 do lookup[chars:byte(i)] = i - 1 end
        local out, buf, bits = {}, 0, 0
        for i = 1, #data do
            local v = lookup[data:byte(i)]
            if v then
                buf = buf * 64 + v; bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    local byte = math.floor(buf / 2 ^ bits)
                    buf = buf % 2 ^ bits
                    out[#out + 1] = string.char(byte)
                end
            end
        end
        return table.concat(out)
    end
    if type(getcustomasset) == "function" and type(isfile) == "function" and type(writefile) == "function" then
        pcall(function()
            for _, p in ipairs({"Orchid", "Orchid/Assets"}) do
                if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(p) then makefolder(p) end
            end
        end)
        local path = "Orchid/Assets/lotus_silver_logo.png"
        local have = false
        pcall(function() have = isfile(path) and #readfile(path) > 500 end)
        if not have then have = pcall(writefile, path, b64decode(LOTUS_LOGO_B64)) end
        if have then pcall(function() LOTUS_LOGO_ID = getcustomasset(path) end) end
    end
end
local introDone = false
local INTRO_T0 = tick()

local function OrchidIntro(done)
    local TweenService = game:GetService("TweenService")
    local Players = game:GetService("Players")
    local PG = Players.LocalPlayer:WaitForChild("PlayerGui")
    local C = Color3.fromRGB
    local WHITE, SIL = Color3.new(1, 1, 1), C(255, 214, 60)
    local ig
    local called = false
    local function finish() if not called then called = true; done() end end
    local function tw(o, t, props, style, dir)
        local x = TweenService:Create(o, TweenInfo.new(t, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
        x:Play()
        return x
    end
    local ok = pcall(function()
        local function mkFont(w)
            local f
            local good = pcall(function() f = Font.new("rbxasset://fonts/families/Montserrat.json", w, Enum.FontStyle.Normal) end)
            return (good and f) or Font.fromEnum(Enum.Font.GothamBold)
        end
        local FT, FS = mkFont(Enum.FontWeight.Bold), mkFont(Enum.FontWeight.Light)
