            if d:GetAttribute("PXW") or d:FindFirstChildOfClass("UIScale") then return end
            if d:IsA("TextButton") and d.BackgroundTransparency >= 1 and d.Text == "" then return end
            local big = d.Size.X.Scale > 0 or d.Size.X.Offset > 240
            local hov, dn = big and 1.004 or 1.015, big and 0.99 or 0.97
