            d.MouseButton1Down:Connect(function() Anim.tw(sc, 0.08, {Scale = dn}, Enum.EasingStyle.Quad) end)
            d.MouseButton1Up:Connect(function() Anim.tw(sc, 0.3, {Scale = over and hov or 1}, Enum.EasingStyle.Back) end)
        elseif d:IsA("ScrollingFrame") then
            d:SetAttribute("PXU", true)
