                d.ImageTransparency = 1; Anim.tw(d, 0.3, {ImageTransparency = it}, Enum.EasingStyle.Quad)
            elseif d:IsA("Frame") and d.BackgroundTransparency < 1 then
                local bt = d.BackgroundTransparency
                d.BackgroundTransparency = 1; Anim.tw(d, 0.3, {BackgroundTransparency = bt}, Enum.EasingStyle.Quad)
            end
        end
    end
    for _, d in ipairs(root:GetDescendants()) do pcall(hook, d) end
    track(root.DescendantAdded:Connect(function(d) task.defer(function() pcall(hook, d) end) end))
