local CFG_READY = false   -- saving is blocked until the saved config has been applied (so defaults never overwrite it)
local function saveConfig()
if type(writefile) ~= "function" then return false end
if not CFG_READY then return true end
local ok = pcall(function() writefile(CONFIG, encode()) end)
if ok then clearDirty() end
return ok
end
function Core.migKey(k)
local MIG = {
{"Player.Slide.", false},
{"Player.Movement.Other.Noclip", "Character.Movement.Collision.Noclip"},
{"Player.Movement.Other.Auto Strafe", "Character.Movement.Air Control.Auto Strafe"},
{"Player.Movement.Flight.", "Character.Flight.Flight."},
{"Player.Movement.Long Jump.", "Character.Long Jump.Long Jump."},
{"Player.Movement.", "Character.Movement."},
{"Player.", "Character."},
}
if type(k) ~= "string" or k:sub(1, 7) ~= "Player." then return k end
for _, m in ipairs(MIG) do
if k:sub(1, #m[1]) == m[1] then
if m[2] == false then return nil end
return m[2] .. k:sub(#m[1] + 1)
end
end
return k
end
local function applyTable(d)
for k0, v in pairs(d) do
local k = Core.migKey(k0)
if k == nil then continue end
CONFIG_VALUES[k] = v
if registry[k] then pcall(registry[k], v) end
end
end
