Position = UDim2.new(1, -16, 1, -16), Size = UDim2.fromOffset(270, 400), ZIndex = 900}, gui)
make("UIListLayout", {VerticalAlignment = Enum.VerticalAlignment.Bottom,
HorizontalAlignment = Enum.HorizontalAlignment.Right, Padding = UDim.new(0, 8),
SortOrder = Enum.SortOrder.LayoutOrder}, notifHolder)
Core.notifScale = make("UIScale", {Name = "AutoScale"}, notifHolder)
local function notify(title, text, dur, kind)
dur = dur or 3.5
local col = (kind == "danger" and Color3.fromRGB(255, 80, 80)) or (kind == "ok" and Color3.fromRGB(80, 225, 120)) or Anim.Gold
local n = make("CanvasGroup", {BackgroundColor3 = T.PanelHi, Size = UDim2.fromOffset(280, 66),
GroupTransparency = 1, ZIndex = 900}, notifHolder)
corner(n, 10); stroke(n, T.Border, 1, 0.2)
make("Frame", {BackgroundColor3 = col, Size = UDim2.new(0, 4, 1, 0), BorderSizePixel = 0}, n)
make("TextLabel", {BackgroundTransparency = 1, Position = UDim2.fromOffset(16, 6), Size = UDim2.new(1, -22, 0, 18),
Text = string.upper(title), FontFace = F_HEAVY, TextSize = 16, TextColor3 = col,
TextXAlignment = Enum.TextXAlignment.Left}, n)
make("TextLabel", {BackgroundTransparency = 1, Position = UDim2.fromOffset(16, 26), Size = UDim2.new(1, -22, 0, 32),
Text = text, FontFace = F_BOLD, TextSize = 17, TextColor3 = T.Text, TextXAlignment = Enum.TextXAlignment.Left,
TextYAlignment = Enum.TextYAlignment.Top, TextWrapped = true}, n)
local bar = make("Frame", {BackgroundColor3 = col, BackgroundTransparency = 0.25, AnchorPoint = Vector2.new(0, 1),
Position = UDim2.fromScale(0, 1), Size = UDim2.new(1, 0, 0, 2), BorderSizePixel = 0}, n)
local ns = make("UIScale", {Scale = 0.72}, n)
n.Rotation = 5; tween(n, 0.7, {Rotation = 0}, Enum.EasingStyle.Back)
tween(ns, 0.5, {Scale = 1}, Enum.EasingStyle.Back)
tween(n, 0.3, {GroupTransparency = 0})
tween(bar, dur, {Size = UDim2.new(0, 0, 0, 2)}, Enum.EasingStyle.Linear)
task.delay(dur, function()
if n.Parent then tween(ns, 0.25, {Scale = 0.8}, Enum.EasingStyle.Quint, Enum.EasingDirection.In); tween(n, 0.25, {GroupTransparency = 1}).Completed:Connect(function() n:Destroy() end) end
end)
end
local WIN_W, WIN_H = 860, 500
local TOP_H, SIDE_W, CARD_H, SQ = 40, 150, 48, 40
local SUB_H, DESC_H = 30, 18
local holder = make("Frame", {Name = "Holder", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(WIN_W, WIN_H)}, gui)
local holderScale = make("UIScale", {Scale = 1}, holder)
local glow = make("Frame", {BackgroundColor3 = T.Accent, BackgroundTransparency = 1, BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
Size = UDim2.fromOffset(WIN_W + 14, WIN_H + 14), Visible = false}, holder)
make("UICorner", {CornerRadius = UDim.new(0, 2)}, glow)
onAccent(function() glow.BackgroundColor3 = T.Accent end)
local shadow = make("ImageLabel", {BackgroundTransparency = 1, ImageColor3 = Color3.new(0, 0, 0), ImageTransparency = 1,
AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
Size = UDim2.fromOffset(WIN_W + 60, WIN_H + 60), Image = "rbxasset://textures/ui/Glow.png", Visible = false}, holder)
local win = make("CanvasGroup", {Name = "Window", BackgroundColor3 = T.Bg, AnchorPoint = Vector2.new(0.5, 0.5),
Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1, 1), GroupTransparency = 1, Visible = false}, holder)
make("UICorner", {CornerRadius = UDim.new(0, 2)}, win)
local winStroke = stroke(win, Color3.new(1, 1, 1), 1, 0.2)
local winGrad = make("UIGradient", {}, winStroke)
onAccent(function()
winGrad.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, T.Accent), ColorSequenceKeypoint.new(0.25, T.AccentHi),
ColorSequenceKeypoint.new(0.5, Anim.Gold), ColorSequenceKeypoint.new(0.75, T.AccentHi), ColorSequenceKeypoint.new(1, T.Accent)})
shadow.ImageColor3 = T.Accent
end)
local winScale = make("UIScale", {Scale = 0.88}, win)
do
local aura = make("ImageLabel", {BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = T.Accent, ImageTransparency = 0.7,
AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(WIN_W + 170, WIN_H + 170), ZIndex = 0, Visible = false}, holder)
onAccent(function() aura.ImageColor3 = T.Accent end)
Anim.loop(aura, "ImageTransparency", 0.5, 0.85, 1.8, true, Enum.EasingStyle.Sine)
Anim.loop(aura, "Size", UDim2.fromOffset(WIN_W + 130, WIN_H + 130), UDim2.fromOffset(WIN_W + 220, WIN_H + 220), 2.4, true, Enum.EasingStyle.Sine)
win:GetPropertyChangedSignal("Visible"):Connect(function() aura.Visible = win.Visible end)
end
Anim.loop(winGrad, "Rotation", 0, 360, 7)
Anim.sparkles(win, gui, UIS.TouchEnabled and 3 or 8)
-- ===== THEME Core ENGINE (per-theme animated effects) =====
do
local fxRoot = make("Frame", {Name = "ThemeFX", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 1, Active = false, ClipsDescendants = true, BorderSizePixel = 0}, win)
local rnd, sin, cos, pi = math.random, math.sin, math.cos, math.pi
local GLOWI = "rbxasset://textures/ui/Glow.png"
local cfg = {on = true, amount = 1, speed = 1, trans = true, o1 = nil, o2 = nil}
local curName = "Orchid"
local parts, perm, active = {}, {}, {}
local MAXP = UIS.TouchEnabled and 40 or 90
local function rr(a, b) return a + (b - a) * rnd() end
local function lerp(a, b, x) return a + (b - a) * x end
local function colA() return rnd() < 0.5 and T.Accent or T.AccentHi end
local function add(life, o, step)
if #parts >= MAXP then o:Destroy(); return end
parts[#parts + 1] = {o = o, age = 0, life = life, step = step}
end
local SP, PERM = {}, {}
SP.embers = {rate = 16, fn = function()
local s, x = rr(2, 4), rr(0, WIN_W)
local o = make("Frame", {BackgroundColor3 = colA(), BorderSizePixel = 0, Size = UDim2.fromOffset(s, s), Position = UDim2.fromOffset(x, WIN_H + 4), ZIndex = 1, Rotation = rnd(0, 90)}, fxRoot)
local vy, vx, ph = rr(45, 120), rr(-12, 12), rnd() * 6
add(rr(3, 6), o, function(p, dt)
local a = p.age / p.life
o.Position = UDim2.fromOffset(x + vx * p.age + sin(p.age * 3 + ph) * 8, WIN_H + 4 - vy * p.age)
o.BackgroundTransparency = math.clamp(0.25 + a * 0.75 + sin(p.age * 18) * 0.12, 0, 1)
end)
end}
SP.snow = {rate = 14, fn = function()
local s, x = rr(2, 4), rr(0, WIN_W)
local o = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromOffset(s, s), Position = UDim2.fromOffset(x, -6), ZIndex = 1}, fxRoot)
local vy, ph = rr(25, 60), rnd() * 6
add(WIN_H / vy + 0.3, o, function(p, dt)
o.Position = UDim2.fromOffset(x + sin(p.age * 1.4 + ph) * 18, -6 + vy * p.age)
o.BackgroundTransparency = 0.25 + 0.5 * (p.age / p.life) ^ 3
end)
end}
SP.petals = {rate = 6, fn = function()
local x = rr(0, WIN_W)
local o = make("Frame", {BackgroundColor3 = T.Accent:Lerp(Color3.new(1, 1, 1), 0.4), BorderSizePixel = 0, Size = UDim2.fromOffset(8, 4), Position = UDim2.fromOffset(x, -8), ZIndex = 1}, fxRoot)
local vy, ph, rot = rr(30, 60), rnd() * 6, rr(-160, 160)
add(WIN_H / vy + 0.4, o, function(p, dt)
o.Position = UDim2.fromOffset(x + sin(p.age * 1.1 + ph) * 34, -8 + vy * p.age)
o.Rotation = ph * 20 + rot * p.age
o.BackgroundTransparency = 0.2 + 0.6 * (p.age / p.life) ^ 3
end)
end}
SP.stars = {rate = 10, fn = function()
local s = rr(1, 3)
local o = make("Frame", {BackgroundColor3 = rnd() < 0.5 and Color3.new(1, 1, 1) or T.AccentHi, BorderSizePixel = 0, Size = UDim2.fromOffset(s, s), Position = UDim2.fromOffset(rr(0, WIN_W), rr(0, WIN_H)), ZIndex = 1, Rotation = 45}, fxRoot)
add(rr(2, 4), o, function(p, dt) o.BackgroundTransparency = 1 - sin((p.age / p.life) * pi) * 0.9 end)
end}
SP.shoot = {rate = 0.35, fn = function()
local ang = rr(20, 40)
local o = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromOffset(80, 1), AnchorPoint = Vector2.new(0.5, 0.5), Rotation = ang, ZIndex = 1}, fxRoot)
make("UIGradient", {Name = "NoTheme", Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0)})}, o)
local x0, y0, v = rr(0, WIN_W * 0.7), rr(0, WIN_H * 0.4), rr(380, 560)
add(0.9, o, function(p, dt)
o.Position = UDim2.fromOffset(x0 + cos(math.rad(ang)) * v * p.age, y0 + sin(math.rad(ang)) * v * p.age)
o.BackgroundTransparency = (p.age / p.life) ^ 2
end)
end}
SP.bubbles = {rate = 3.5, fn = function()
local s, x = rr(6, 16), rr(0, WIN_W)
local o = make("Frame", {BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromOffset(s, s), Position = UDim2.fromOffset(x, WIN_H + 10), ZIndex = 1}, fxRoot)
local st = make("UIStroke", {Color = colA(), Thickness = 1, Transparency = 0.3}, o)
local vy, ph = rr(18, 40), rnd() * 6
add(rr(5, 9), o, function(p, dt)
o.Position = UDim2.fromOffset(x + sin(p.age * 1.6 + ph) * 10, WIN_H + 10 - vy * p.age)
st.Transparency = 0.3 + 0.7 * (p.age / p.life) ^ 2
end)
end}
SP.rain = {rate = 6, fn = function()
local n, x = rnd(6, 14), rr(0, WIN_W)
local chars, t = "01ABCDEF<>/|+=#", {}
for i = 1, n do local k = rnd(1, #chars); t[i] = chars:sub(k, k) end
local o = make("TextLabel", {BackgroundTransparency = 1, Text = table.concat(t, "\n"), Font = Enum.Font.Code, TextSize = 12, TextColor3 = T.Accent, Size = UDim2.fromOffset(10, n * 12), Position = UDim2.fromOffset(x, -n * 12), ZIndex = 1, TextYAlignment = Enum.TextYAlignment.Top, LineHeight = 1}, fxRoot)
make("UIGradient", {Name = "NoTheme", Rotation = 90, Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.1)})}, o)
local vy = rr(140, 260)
add((WIN_H + n * 12) / vy, o, function(p, dt) o.Position = UDim2.fromOffset(x, -n * 12 + vy * p.age) end)
end}
SP.glitch = {rate = 3, fn = function()
local o = make("Frame", {BackgroundColor3 = ({T.Accent, T.AccentHi, Color3.new(1, 1, 1)})[rnd(1, 3)], BorderSizePixel = 0, BackgroundTransparency = 0.6,
Size = UDim2.fromOffset(WIN_W, rr(2, 10)), Position = UDim2.fromOffset(rr(-14, 14), rr(0, WIN_H)), ZIndex = 1}, fxRoot)
add(0.16, o, function(p, dt) o.Visible = rnd() < 0.6 end)
end}
SP.pulse = {rate = 0.5, fn = function()
local o = make("Frame", {BackgroundTransparency = 1, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(30, 30), Position = UDim2.fromOffset(WIN_W * 0.5, WIN_H * 0.5), ZIndex = 1}, fxRoot)
local st = make("UIStroke", {Color = colA(), Thickness = 2, Transparency = 0.2}, o)
add(3.2, o, function(p, dt)
local a = p.age / p.life
local d = lerp(30, 980, 1 - (1 - a) ^ 2)
o.Size = UDim2.fromOffset(d, d); o.Rotation = a * 90; st.Transparency = 0.2 + 0.8 * a
end)
end}
SP.lightning = {rate = 0.22, fn = function()
local fl = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 2, BackgroundTransparency = 0.88}, fxRoot)
add(0.35, fl, function(p, dt) fl.BackgroundTransparency = 0.88 + 0.12 * (p.age / p.life) end)
local c = make("Frame", {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 2}, fxRoot)
local x, y, segs = rr(60, WIN_W - 60), 0, 8
for i = 1, segs do
local dx, dy = rr(-24, 24), WIN_H / segs
make("Frame", {BackgroundColor3 = i % 2 == 0 and Color3.new(1, 1, 1) or T.AccentHi, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5),
Size = UDim2.fromOffset(2, math.sqrt(dx * dx + dy * dy)), Position = UDim2.fromOffset(x + dx / 2, y + dy / 2), Rotation = -math.deg(math.atan2(dx, dy)), ZIndex = 2}, c)
x, y = x + dx, y + dy
end
add(0.3, c, function(p, dt) c.Visible = rnd() < 0.75 end)
end}
SP.orbs = {rate = 3, fn = function()
local s = rr(14, 30)
local o = make("ImageLabel", {BackgroundTransparency = 1, Image = GLOWI, ImageColor3 = colA(), AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(s, s), ZIndex = 1, ImageTransparency = 1}, fxRoot)
local bx, by, f1, f2, ph = rr(0, WIN_W), rr(0, WIN_H), rr(0.4, 1.1), rr(0.4, 1.1), rnd() * 6
add(rr(5, 8), o, function(p, dt)
o.Position = UDim2.fromOffset(bx + sin(p.age * f1 + ph) * 34, by + cos(p.age * f2 + ph) * 24 - p.age * 6)
o.ImageTransparency = 1 - sin((p.age / p.life) * pi) * 0.7
end)
end}
PERM.sheen = function()
local o = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(110, WIN_H * 2), Rotation = 20, ZIndex = 1, Position = UDim2.fromOffset(-300, WIN_H / 2)}, fxRoot)
make("UIGradient", {Name = "NoTheme", Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0.8), NumberSequenceKeypoint.new(1, 1)})}, o)
return {o}, function(t, dt)
local c = (t * 0.2) % 1
o.Visible = c < 0.4
o.Position = UDim2.fromOffset(lerp(-200, WIN_W + 200, math.clamp(c / 0.4, 0, 1)), WIN_H / 2)
end
end
PERM.scan = function()
local o = make("Frame", {BackgroundColor3 = T.Accent, BorderSizePixel = 0, Size = UDim2.fromOffset(WIN_W, 70), ZIndex = 1}, fxRoot)
make("UIGradient", {Name = "NoTheme", Rotation = 90, Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.9, 0.86), NumberSequenceKeypoint.new(1, 0.5)})}, o)
return {o}, function(t, dt) o.Position = UDim2.fromOffset(0, ((t * 0.22) % 1) * (WIN_H + 70) - 70) end
end
PERM.aurora = function()
local objs = {}
for i = 1, 3 do
objs[i] = make("ImageLabel", {BackgroundTransparency = 1, Image = GLOWI, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(WIN_W * 0.7, 170),
ImageColor3 = i == 2 and T.AccentHi or T.Accent, ImageTransparency = 0.7, ZIndex = 1}, fxRoot)
end
return objs, function(t, dt)
for i, g in ipairs(objs) do
g.Position = UDim2.fromOffset(WIN_W * (0.2 + 0.3 * i) + sin(t * 0.4 + i * 2) * WIN_W * 0.18, 40 + sin(t * 0.6 + i) * 30 + i * 14)
g.ImageTransparency = 0.62 + 0.15 * sin(t * 0.9 + i * 1.7)
end
end
end
PERM.grid = function()
local objs, lines = {}, {}
local hy = WIN_H * 0.58
for i = 1, 9 do
lines[i] = make("Frame", {BackgroundColor3 = T.Accent, BorderSizePixel = 0, Size = UDim2.fromOffset(WIN_W, 1), ZIndex = 1}, fxRoot); objs[#objs + 1] = lines[i]
end
objs[#objs + 1] = make("Frame", {BackgroundColor3 = T.AccentHi, BorderSizePixel = 0, BackgroundTransparency = 0.5, Size = UDim2.fromOffset(WIN_W, 1), Position = UDim2.fromOffset(0, hy), ZIndex = 1}, fxRoot)
for i = 0, 12 do
local xb = WIN_W * (i / 12 * 2.4 - 0.7)
local dx, dy = xb - WIN_W / 2, WIN_H - hy
objs[#objs + 1] = make("Frame", {BackgroundColor3 = T.Accent, BorderSizePixel = 0, BackgroundTransparency = 0.78, AnchorPoint = Vector2.new(0.5, 0.5),
Size = UDim2.fromOffset(1, math.sqrt(dx * dx + dy * dy)), Position = UDim2.fromOffset(WIN_W / 2 + dx / 2, hy + dy / 2), Rotation = -math.deg(math.atan2(dx, dy)), ZIndex = 1}, fxRoot)
end
return objs, function(t, dt)
for i, l in ipairs(lines) do
local f = (t * 0.18 + i / 9) % 1
l.Position = UDim2.fromOffset(0, hy + (WIN_H - hy) * f * f)
l.BackgroundTransparency = 0.9 - 0.5 * f
end
end
end
local FXMAP = {
Orchid = {"orbs", "embers", "sheen", "stars", "shoot"}, Rose = {"petals", "orbs"}, Crimson = {"embers", "scan"}, Synthwave = {"grid", "scan", "stars"},
Midnight = {"stars", "shoot", "aurora"}, Sakura = {"petals", "orbs"}, Mocha = {"orbs", "bubbles"}, Dracula = {"lightning", "embers"},
["Tokyo Night"] = {"rain", "glitch"}, ["Rose Pine"] = {"petals", "snow"}, Nord = {"snow", "aurora"}, Gruvbox = {"embers", "scan"},
Aurora = {"aurora", "stars"}, Inferno = {"embers", "embers", "lightning"}, Cyberpunk = {"glitch", "scan", "rain"}, Ocean = {"bubbles", "aurora"},
Matrix = {"rain", "scan"}, Monochrome = {"sheen", "pulse"}, Vaporwave = {"grid", "pulse", "stars"}, ["Blood Moon"] = {"embers", "pulse", "lightning"},
Toxic = {"bubbles", "glitch"}, Abyss = {"bubbles", "pulse", "aurora"}, ["Gold Rush"] = {"sheen", "embers"}, ["Lavender Haze"] = {"orbs", "petals", "aurora"},
["Neon Mint"] = {"rain", "pulse"}, Sunset = {"aurora", "embers"}, Galaxy = {"stars", "shoot", "pulse"}, Ice = {"snow", "sheen"},
Lava = {"embers", "pulse"}, ["Cherry Cola"] = {"bubbles", "orbs"}, Emerald = {"aurora", "orbs"}, Royal = {"sheen", "stars"},
Candy = {"bubbles", "petals"}, Void = {"pulse", "stars", "glitch"}, Ember = {"embers"}, Hologram = {"scan", "glitch", "grid"},
["Black Hole"] = {"pulse", "stars", "orbs"}, Thunderstorm = {"rain", "lightning", "pulse"}, Hellfire = {"embers", "lightning", "glitch"},
Glacier = {"snow", "sheen", "aurora"}, ["Retro Arcade"] = {"grid", "scan", "glitch"}, Fireflies = {"orbs", "stars"},
["Cherry Blossom"] = {"petals", "orbs", "sheen"}, ["Deep Sea"] = {"bubbles", "aurora", "pulse"}, ["Solar Flare"] = {"embers", "pulse", "sheen"},
Glitchcore = {"glitch", "rain", "scan"}, ["Zen Night"] = {"petals", "stars", "orbs"}, ["Neon Noir"] = {"scan", "pulse", "shoot"},
["Cosmic Dust"] = {"stars", "shoot", "aurora", "orbs"}, Platinum = {"sheen", "shoot", "stars"}, Custom = {"sheen", "orbs"},
}
local function rebuild()
for _, p in ipairs(parts) do pcall(function() p.o:Destroy() end) end
table.clear(parts)
for _, q in ipairs(perm) do for _, o in ipairs(q.objs) do pcall(function() o:Destroy() end) end end
table.clear(perm); table.clear(active)
fxRoot.Visible = cfg.on
if cfg.on then
local m1 = make("ImageLabel", {BackgroundTransparency = 1, Image = GLOWI, ImageColor3 = T.Accent, ImageTransparency = 0.78, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(0, 0), Size = UDim2.fromOffset(WIN_W * 0.9, WIN_H * 0.9), ZIndex = 1}, fxRoot)
local m2 = make("ImageLabel", {BackgroundTransparency = 1, Image = GLOWI, ImageColor3 = T.AccentHi, ImageTransparency = 0.84, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(WIN_W, WIN_H), Size = UDim2.fromOffset(WIN_W * 0.9, WIN_H * 0.9), ZIndex = 1}, fxRoot)
perm[#perm + 1] = {objs = {m1, m2}, upd = function() end}
end
local list = {}
if cfg.o1 then list[1] = cfg.o1 else for _, n in ipairs(FXMAP[curName] or {"sheen"}) do list[#list + 1] = n end end
if cfg.o2 then list[#list + 1] = cfg.o2 end
local seen = {}
for _, n in ipairs(list) do
if not seen[n] then
seen[n] = true
if SP[n] then active[#active + 1] = {sp = SP[n], acc = 0}
elseif PERM[n] then local objs, upd = PERM[n](); perm[#perm + 1] = {objs = objs, upd = upd} end
end
end
end
local tt, last = 0, os.clock()
local conn = RunService.RenderStepped:Connect(function()
local now = os.clock()
local dt = math.min(now - last, 0.05); last = now
if not cfg.on or not win.Visible or win.GroupTransparency > 0.95 then return end
dt = dt * cfg.speed; tt = tt + dt
for _, e in ipairs(active) do
e.acc = e.acc + dt * e.sp.rate * cfg.amount
while e.acc >= 1 do e.acc = e.acc - 1; pcall(e.sp.fn) end
end
for i = #parts, 1, -1 do
local p = parts[i]
p.age = p.age + dt
if p.age >= p.life or not p.o.Parent then
pcall(function() p.o:Destroy() end); table.remove(parts, i)
else pcall(p.step, p, dt) end
end
for _, q in ipairs(perm) do pcall(q.upd, tt, dt) end
end)
if type(track) == "function" then track(conn) end
Core.ThemeFX = {cfg = cfg, effects = {}}
function Core.ThemeFX.set(name) curName = name; rebuild() end
function Core.ThemeFX.refresh() rebuild() end
function Core.ThemeFX.chaos()
local pool = {}
for k in pairs(SP) do pool[#pool + 1] = k end
for k in pairs(PERM) do pool[#pool + 1] = k end
cfg.o1 = pool[rnd(#pool)]; cfg.o2 = pool[rnd(#pool)]
end
function Core.ThemeFX.transition()
if not cfg.trans or not win.Visible then return end
pcall(function()
holderScale.Scale = 0.955
Anim.tw(holderScale, 0.55, {Scale = 1}, Enum.EasingStyle.Back)
local bar = make("Frame", {BackgroundColor3 = T.AccentHi, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(150, WIN_H * 2), Rotation = 18, ZIndex = 3, BackgroundTransparency = 0.45, Position = UDim2.fromOffset(-200, WIN_H / 2)}, fxRoot)
make("UIGradient", {Name = "NoTheme", Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1)})}, bar)
Anim.tw(bar, 0.8, {Position = UDim2.fromOffset(WIN_W + 200, WIN_H / 2)}, Enum.EasingStyle.Quint)
task.delay(0.9, function() bar:Destroy() end)
end)
end
rebuild()
end

Core.Flame = {on = true, n = UIS.TouchEnabled and 24 or 44}
do
local F = Core.Flame
local GLOW = "rbxasset://textures/ui/Glow.png"
local overlay = make("Frame", {Name = "Flame", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 0, Active = false}, gui)
local halo = make("ImageLabel", {BackgroundTransparency = 1, Image = GLOW, AnchorPoint = Vector2.new(0.5, 0.5),
ImageTransparency = 1, ZIndex = 0, Visible = false}, overlay)
local pool, active = {}, {}
local function newSprite()
return make("ImageLabel", {BackgroundTransparency = 1, Image = GLOW, AnchorPoint = Vector2.new(0.5, 0.5),
ImageTransparency = 1, Visible = false, ZIndex = 1}, overlay)
end
local rnd, WHITE = math.random, Color3.new(1, 1, 1)
local hx, hy, hvx, hvy = nil, nil, 0, 0
local last, acc, spawnAcc = os.clock(), 0, 0
local function spawnOne(px, py, pw, ph, sc)
local r, x, y, vx = rnd(), 0, 0, 0
if r < 0.30 then x, y, vx = px + rnd() * pw, py + 2, (rnd() - 0.5) * 30
elseif r < 0.57 then x, y, vx = px + 2, py + rnd() * ph, -rnd() * 35
elseif r < 0.84 then x, y, vx = px + pw - 2, py + rnd() * ph, rnd() * 35
else x, y, vx = px + rnd() * pw, py + ph - 2, (rnd() - 0.5) * 70 end
active[#active + 1] = {s = table.remove(pool) or newSprite(), x = x, y = y, vx = vx * sc, vy = -(55 + rnd() * 75) * sc,
age = 0, life = 0.7 + rnd() * 0.8, size = (20 + rnd() * 22) * sc, ph = rnd() * 6.28}
end
track(RunService.RenderStepped:Connect(function()
local now = os.clock()
acc += now - last; last = now
if acc < (UIS.TouchEnabled and 1 / 30 or 1 / 60) then return end
local dt = math.min(acc, 0.06); acc = 0
local vis = F.on and win.Visible
local alpha = vis and (1 - win.GroupTransparency) or 0
if not vis and #active == 0 then halo.Visible = false; hx = nil; return end
local ap, asz, off = holder.AbsolutePosition, holder.AbsoluteSize, overlay.AbsolutePosition
if hx then
local k = math.min(1, dt * 12)
hvx += ((ap.X - hx) / dt - hvx) * k; hvy += ((ap.Y - hy) / dt - hvy) * k
end
hx, hy = ap.X, ap.Y
local sc = holderScale.Scale
local aB, aA, bg = T.AccentHi, T.Accent, T.Bg
halo.Visible = alpha > 0.01
halo.Position = UDim2.fromOffset(ap.X + asz.X / 2 - off.X, ap.Y + asz.Y / 2 - off.Y)
halo.Size = UDim2.fromOffset(asz.X * 1.4, asz.Y * 1.5)
halo.ImageColor3 = aA
local fl = 0.5 + 0.25 * math.sin(now * 9.3) + 0.15 * math.sin(now * 3.1 + 1) + 0.1 * math.sin(now * 17)
halo.ImageTransparency = 1 - math.clamp((0.14 + 0.1 * fl) * alpha, 0, 1)
if vis and alpha > 0.2 then
local want = math.clamp(F.n, 0, 120)
spawnAcc += dt * want / 1.1
local g = 0
while spawnAcc >= 1 and #active < want * 1.3 and g < 8 do
spawnAcc -= 1; g += 1; spawnOne(ap.X, ap.Y, asz.X, asz.Y, sc)
end
if spawnAcc > 3 then spawnAcc = 0 end
else spawnAcc = 0 end
local hot = aB:Lerp(WHITE, 0.65)
local i = 1
while i <= #active do
local p = active[i]
p.age += dt
local t = p.age / p.life
if t >= 1 then
p.s.Visible = false
if #pool < 140 then pool[#pool + 1] = p.s else p.s:Destroy() end
active[i] = active[#active]; active[#active] = nil
else
p.vy -= 55 * sc * dt
p.vx += math.sin(now * 7 + p.ph + p.y * 0.03) * 70 * sc * dt
p.vx -= hvx * 0.9 * dt; p.vy -= hvy * 0.9 * dt
p.vx *= 1 - math.min(1, 1.4 * dt); p.vy *= 1 - math.min(1, 0.5 * dt)
p.x += p.vx * dt; p.y += p.vy * dt
local col
if t < 0.2 then col = hot:Lerp(aB, t / 0.2)
elseif t < 0.6 then col = aB:Lerp(aA, (t - 0.2) / 0.4)
else col = aA:Lerp(bg, math.min(1, (t - 0.6) / 0.4 * 0.85)) end
local a = math.min(1, t / 0.1) * (1 - t) ^ 1.3
local sz = p.size * (1 - 0.7 * t)
local s = p.s
s.Visible = true
s.ImageColor3 = col
s.ImageTransparency = 1 - math.clamp(a * 0.6 * alpha, 0, 1)
s.Size = UDim2.fromOffset(sz, sz * 1.8)
s.Position = UDim2.fromOffset(p.x - off.X, p.y - off.Y)
s.Rotation = math.clamp(p.vx * 0.15, -25, 25)
i += 1
end
end
end))
end
for _, o in ipairs(Lighting:GetChildren()) do if o.Name == "OrchidBlur" then o:Destroy() end end
