local function selectSub(m, s)
if activeSub == s then return end
if not s or not s.page or not s.btn or not s.line then return end
if activeSub then
pcall(function()
activeSub.page.Visible = false
activeSub.btn.TextColor3 = T.Sub; activeSub.btn.FontFace = F_BOLD; activeSub.btn.TextStrokeTransparency = 1
activeSub.line.Size = UDim2.new(0, 0, 0, 1)
end)
end
activeSub = s
m.lastSub = s
s.page.Visible = true
s.page.CanvasPosition = Vector2.new(0, 0)
filterPage(s.page)
descLabel.Text = s.desc or ""
crumb.Text = string.upper(m.display or m.name) .. "   >   " .. string.upper(s.name)
s.btn.TextColor3 = T.Text; s.btn.FontFace = F_BOLD
s.line.Size = UDim2.new(1, -14, 0, 1)
s.page.Position = UDim2.fromOffset(0, 0)
