crumb.Position = UDim2.new(0.5, 24, 0.5, 1)
descLabel.TextTransparency = 0
end
local function selectMain(m)
if activeMain == m then return end
if activeMain then
activeMain.bar.scroll.Visible = false
tween(activeMain.item, 0.18, {BackgroundTransparency = 1})
tween(activeMain.itemLbl, 0.18, {TextColor3 = T.Sub}); activeMain.itemLbl.FontFace = F_BOLD; activeMain.itemLbl.TextStrokeTransparency = 1
tween(activeMain.itemLbl, 0.3, {Position = UDim2.fromOffset(18, 0)}, Enum.EasingStyle.Back)
tween(activeMain.itemBar, 0.18, {BackgroundTransparency = 1, Size = UDim2.fromOffset(2, 6)})
if activeSub then pcall(function() activeSub.page.Visible = false end); activeSub = nil end
end
activeMain = m
m.bar.scroll.Visible = true
m.bar.scroll.Position = UDim2.fromOffset(10, 4)
tween(m.item, 0.18, {BackgroundTransparency = 0.8})
tween(m.itemLbl, 0.18, {TextColor3 = T.Text}); m.itemLbl.FontFace = F_BOLD
tween(m.itemLbl, 0.35, {Position = UDim2.fromOffset(23, 0)}, Enum.EasingStyle.Back)
tween(m.itemBar, 0.24, {BackgroundTransparency = 0, Size = UDim2.fromOffset(2, 14)}, Enum.EasingStyle.Back)
if m.subs[1] then
local okS = pcall(selectSub, m, m.lastSub or m.subs[1])
if not okS then pcall(selectSub, m, m.subs[1]) end
end
end
