end
function API.Label(text)
local f = rowBase(24, text)
local l = rowLabel(f, text)
l.TextColor3 = T.Sub; l.TextSize = math.floor(17 * Core.Scale + 0.5)
return {Set = function(_, t) l.Text = t end}
end
function API.Toggle(text, default, cb, hide)
local key = keyOf(text)
local def = default and true or false
if CONFIG_VALUES[key] ~= nil then default = CONFIG_VALUES[key] end
local f = rowBase(27, text)
f.ClipsDescendants = true
local lbl = rowLabel(f, text, -64)
local WHITE = Color3.new(1, 1, 1)
local OFF, OFFLINE, KOFF = Color3.fromRGB(34, 34, 44), Color3.fromRGB(78, 78, 94), Color3.fromRGB(170, 170, 188)
local wash = make("Frame", {BackgroundColor3 = T.Accent, BackgroundTransparency = 1, BorderSizePixel = 0,
Size = UDim2.fromScale(1, 1), ZIndex = 3}, f)
make("UIGradient", {Name = "NoTheme", Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1),
NumberSequenceKeypoint.new(0.45, 0.97), NumberSequenceKeypoint.new(1, 0.8)})}, wash)
local track = make("Frame", {BackgroundColor3 = OFF, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0),
Size = UDim2.fromOffset(36, 18), BorderSizePixel = 0, ZIndex = 5}, f)
make("UICorner", {CornerRadius = UDim.new(1, 0)}, track)
local ts = stroke(track, OFFLINE, 1, 0)
local glow = make("UIStroke", {Color = T.AccentHi, Thickness = 3.5, Transparency = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, track)
local sheen = make("UIGradient", {Name = "NoTheme", Rotation = 90, Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(190, 190, 200))}, track)
local knob = make("Frame", {BackgroundColor3 = KOFF, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 3, 0.5, 0),
Size = UDim2.fromOffset(12, 12), BorderSizePixel = 0, ZIndex = 6}, track)
make("UICorner", {CornerRadius = UDim.new(1, 0)}, knob)
local kScale = make("UIScale", {Scale = 1}, knob)
local edge = f:FindFirstChild("Edge")
local state = default and true or false
local function paint(on)
tween(track, 0.28, {BackgroundColor3 = on and T.Accent or OFF})
tween(ts, 0.28, {Color = on and T.AccentHi or OFFLINE})
tween(glow, 0.35, {Transparency = on and 0.72 or 1})
tween(knob, 0.34, {Position = on and UDim2.new(1, -15, 0.5, 0) or UDim2.new(0, 3, 0.5, 0),
BackgroundColor3 = on and WHITE or KOFF}, Enum.EasingStyle.Back)
tween(wash, 0.25, {BackgroundTransparency = on and 0 or 1})
tween(lbl, 0.18, {TextColor3 = on and T.Text or T.Sub})
tween(lbl, 0.3, {Position = UDim2.fromOffset(on and 18 or 12, 0)}, Enum.EasingStyle.Back)
f:SetAttribute("On", on)
if edge then tween(edge, 0.2, {BackgroundTransparency = on and 0 or 1}) end
end
local function pop()
tween(kScale, 0.07, {Scale = 1.35}).Completed:Connect(function()
tween(kScale, 0.28, {Scale = 1}, Enum.EasingStyle.Back)
end)
end
local function burst()
local ring = make("Frame", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
Position = UDim2.new(1, -30, 0.5, 0), Size = UDim2.fromOffset(18, 18), ZIndex = 4}, f)
make("UICorner", {CornerRadius = UDim.new(1, 0)}, ring)
local rs = stroke(ring, T.AccentHi, 2, 0.1)
tween(ring, 0.5, {Size = UDim2.fromOffset(54, 54)})
tween(rs, 0.5, {Transparency = 1}).Completed:Connect(function() ring:Destroy() end)
end
local function set(v, silent)
state = v and true or false
CONFIG_VALUES[key] = state
if not hide and not (key:find("^Settings%.") or key:find("^Configs%.")) then
ENABLED[key] = state and text or nil
if arrayRefresh and not LOADING then arrayRefresh() end
end
paint(state)
if not silent and not LOADING then pop(); if state then burst() end end
if badgeRefresh and not LOADING then badgeRefresh() end
if cb and not silent then task.spawn(cb, state) end
end
local hit = make("TextButton", {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = "", ZIndex = 6}, f)
hoverRow(f, hit)
hit.MouseEnter:Connect(function() tween(kScale, 0.18, {Scale = 1.15}, Enum.EasingStyle.Back) end)
hit.MouseLeave:Connect(function() tween(kScale, 0.2, {Scale = 1}) end)
hit.MouseButton1Click:Connect(function()
clickSfx(); markDirty()
local m = UIS:GetMouseLocation()
ripple(f, m.X, m.Y - 36)
set(not state)
end)
hit.MouseButton2Click:Connect(function() clickSfx(); markDirty(); set(def) end)
set(state, true)
onAccent(function()
if state then track.BackgroundColor3 = T.Accent; ts.Color = T.AccentHi end
glow.Color = T.AccentHi
wash.BackgroundColor3 = T.Accent
end)
registry[key] = function(v) set(v) end
resetters[key] = function() set(def) end
toggleKeys[key] = true
if cb and state then task.spawn(cb, state) end
return {Set = function(_, v) set(v) end}
end
function API.Slider(text, min, max, default, cb, step)
local key = keyOf(text)
step = step or 1
local def = default
if CONFIG_VALUES[key] ~= nil then default = CONFIG_VALUES[key] end
local f = rowBase(48, text)
local lb = rowLabel(f, text, -100)
lb.Position = UDim2.fromOffset(12, 6); lb.Size = UDim2.new(1, -100, 0, 20)
local val = make("TextBox", {BackgroundColor3 = T.PanelHi, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 5),
Size = UDim2.fromOffset(64, 22), FontFace = F_HEAVY, TextSize = 17, TextColor3 = T.AccentHi, Text = "",
ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 5}, f)
corner(val, 4); stroke(val, T.Border, 1, 0.5)
local bar = make("Frame", {Position = UDim2.new(0, 12, 1, -16), Size = UDim2.new(1, -24, 0, 6),
BackgroundColor3 = T.Border, BorderSizePixel = 0, ZIndex = 4}, f)
corner(bar, 3)
local fill = make("Frame", {Size = UDim2.fromScale(0, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 5}, bar)
corner(fill, 3)
local fillGrad = make("UIGradient", {}, fill)
local knob = make("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5),
Size = UDim2.fromOffset(14, 14), BackgroundColor3 = Color3.new(1, 1, 1), ZIndex = 6}, bar)
corner(knob, 7)
local ks = stroke(knob, T.Accent, 1.5, 0.1)
onAccent(function() fillGrad.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, T.Accent), ColorSequenceKeypoint.new(0.6, T.AccentHi), ColorSequenceKeypoint.new(1, Anim.Gold)}); ks.Color = T.Accent; val.TextColor3 = T.AccentHi end)
local function setValue(v, silent)
v = math.clamp(math.floor(v / step + 0.5) * step, min, max)
v = tonumber(string.format("%.4f", v))
local a = (v - min) / math.max(1e-9, (max - min))
val.Text = string.format("%g", v)
tween(fill, 0.22, {Size = UDim2.fromScale(a, 1)}, Enum.EasingStyle.Quint)
tween(knob, 0.22, {Position = UDim2.fromScale(a, 0.5)}, Enum.EasingStyle.Quint)
CONFIG_VALUES[key] = v
if cb and not silent then task.spawn(cb, v) end
end
setValue(default, true)
if cb then task.spawn(cb, CONFIG_VALUES[key]) end
val.FocusLost:Connect(function()
local typed = tonumber(val.Text)
if typed then setValue(typed); markDirty() else setValue(CONFIG_VALUES[key], true) end
end)
local dragging = false
local function update(i)
local rel = (i.Position.X - bar.AbsolutePosition.X) / math.max(1, bar.AbsoluteSize.X)
setValue(min + (max - min) * math.clamp(rel, 0, 1))
markDirty()
end
f.InputBegan:Connect(function(i)
if isPress(i) then
local p, ap, as = i.Position, val.AbsolutePosition, val.AbsoluteSize
if p.X >= ap.X and p.X <= ap.X + as.X and p.Y >= ap.Y and p.Y <= ap.Y + as.Y then return end
dragging = true; update(i)
tween(knob, 0.3, {Size = UDim2.fromOffset(21, 21)}, Enum.EasingStyle.Back); tween(ks, 0.2, {Thickness = 4, Color = Anim.Gold})
i.Changed:Connect(function()
if i.UserInputState == Enum.UserInputState.End then
dragging = false; tween(knob, 0.35, {Size = UDim2.fromOffset(14, 14)}, Enum.EasingStyle.Back); tween(ks, 0.25, {Thickness = 1.5, Color = T.Accent})
end
end)
end
end)
track(UIS.InputChanged:Connect(function(i) if dragging and isMove(i) then update(i) end end))
hoverRow(f, f)
registry[key] = function(v) setValue(v) end
resetters[key] = function() setValue(def) end
f.InputBegan:Connect(function(i)
if i.UserInputType == Enum.UserInputType.MouseButton2 then clickSfx(); markDirty(); setValue(def) end
end)
if cb then task.spawn(cb, CONFIG_VALUES[key]) end
return {Set = function(_, v) setValue(v) end, Frame = f}
end
function API.Button(text, cb, iconKind)
