local wmLbl = function(g) return make("TextLabel", {BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0),
    Text = "", FontFace = F_HEAVY, TextSize = 17, TextColor3 = T.Text, LayoutOrder = 2, ZIndex = 6}, g) end
-- player icon (head + shoulders)
local gName = wmGroup(2); local icName = wmIcon(gName)
wmPart(icName, 5, 1, 6, 6, 1)
wmPart(icName, 2, 9, 12, 7, 0.5)
local lblName = wmLbl(gName)
-- fps icon (microchip)
local gFps = wmGroup(3); local icFps = wmIcon(gFps)
for _, p in ipairs({4, 7, 10}) do
    wmPart(icFps, p, 0, 2, 3); wmPart(icFps, p, 13, 2, 3)
    wmPart(icFps, 0, p, 3, 2); wmPart(icFps, 13, p, 3, 2)
end
wmPart(icFps, 3, 3, 10, 10, 0.18)
wmPart(icFps, 6, 6, 4, 4, 0.2, Color3.fromRGB(12, 12, 15))
local lblFps = wmLbl(gFps)
-- ping icon (4 bars, reacts to ping)
local gPing = wmGroup(4); local icPing = wmIcon(gPing)
local pingBars = {}
for i = 1, 4 do
    local h = 3 + i * 3
    local b = make("Frame", {BackgroundColor3 = Color3.fromRGB(90, 230, 130), BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1),
    Position = UDim2.fromOffset((i - 1) * 4, 15), Size = UDim2.fromOffset(3, h), ZIndex = 7}, icPing)
    make("UICorner", {CornerRadius = UDim.new(0, 2)}, b)
    pingBars[i] = {f = b, h = h}
end
local lblPing = wmLbl(gPing)
onAccent(function() for _, f in ipairs(wmTint) do f.BackgroundColor3 = T.AccentHi end; wmText.TextColor3 = T.AccentHi end)
local lastLvl = 0
local function pingLevel(ms)
    if ms <= 0 then return 4, Color3.fromRGB(90, 230, 130) end
    if ms < 70 then return 4, Color3.fromRGB(90, 230, 130)
    elseif ms < 120 then return 3, Color3.fromRGB(190, 232, 85)
    elseif ms < 190 then return 2, Color3.fromRGB(255, 170, 70) end
    return 1, Color3.fromRGB(255, 85, 95)
end
function wmRefresh()
    gName.Visible = HUD.name and true or false
    gFps.Visible = HUD.fps and true or false
    gPing.Visible = HUD.ping and true or false
    lblName.Text = player.DisplayName
    lblFps.Text = fpsValue .. " fps"
    local ms = getPing()
    local lvl, col = pingLevel(ms)
    lblPing.Text = ms .. " ms"
    tween(lblPing, 0.3, {TextColor3 = col})
    for i, b in ipairs(pingBars) do
        local on = i <= lvl
        tween(b.f, 0.3, {BackgroundColor3 = on and col or Color3.fromRGB(120, 120, 132), BackgroundTransparency = on and 0 or 0.7})
        if lvl ~= lastLvl then
            tween(b.f, 0.12, {Size = UDim2.fromOffset(3, b.h + 3)}, Enum.EasingStyle.Quad)
            task.delay(0.12, function() if b.f.Parent then tween(b.f, 0.3, {Size = UDim2.fromOffset(3, b.h)}, Enum.EasingStyle.Back) end end)
        end
    end
    lastLvl = lvl
end
end)
