elseif p == "Bottom Left" then wm.AnchorPoint = Vector2.new(0, 1); wm.Position = UDim2.new(0, 12, 1, -12)
else wm.AnchorPoint = Vector2.new(1, 1); wm.Position = UDim2.new(1, -12, 1, -12) end
end
