local kRows, kSig = {}, ""
local function kbRefresh()
local items = {}
for _, e in ipairs(Core.KB) do
local v = CONFIG_VALUES[e.key]
if v and v ~= "" and v ~= "None" then items[#items + 1] = {name = e.text, key = tostring(v)} end
end
local sig = {}
for _, it in ipairs(items) do sig[#sig + 1] = it.name .. "=" .. it.key end
sig = table.concat(sig, "|")
if sig ~= kSig then
kSig = sig
for _, r in ipairs(kRows) do r:Destroy() end
kRows = {}
for i, it in ipairs(items) do
local row = make("Frame", {BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 18), LayoutOrder = 1 + i, ZIndex = 6}, kp)
make("TextLabel", {BackgroundTransparency = 1, Size = UDim2.new(1, -64, 1, 0), Text = it.name, FontFace = F_BOLD, TextSize = 14,
TextColor3 = T.Sub, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 7}, row)
make("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromScale(1, 0), Size = UDim2.new(0, 60, 1, 0),
Text = "[" .. it.key .. "]", FontFace = F_HEAVY, TextSize = 14, TextColor3 = T.AccentHi, TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 7}, row)
kRows[#kRows + 1] = row
end
end
kp.Visible = (not IS_MOBILE) and HUD.on and HUD.kb and #kRows > 0
end
