------------------------------------------------------------------ HOME TAB
local function timeGreet()
local hr = tonumber(os.date("%H")) or 12
if hr < 5 then return "Burning the midnight oil" end
if hr < 12 then return "Good morning" end
if hr < 18 then return "Good afternoon" end
return "Good evening"
end

local function copyText(txt, what)
    local fn = setclipboard or toclipboard or (syn and syn.clipboard_set) or (Clipboard and Clipboard.set)
    if fn then pcall(fn, txt); notify("Copied", what .. " copied to clipboard", 2, "ok")
    else notify("Clipboard", "Your executor has no clipboard function", 2.5, "danger") end
end
local function rejoin()
    local TS = game:GetService("TeleportService")
    notify("Rejoin", "Teleporting you back in...", 3)
    task.wait(0.6)
    if #Players:GetPlayers() <= 1 then
        pcall(function() player:Kick("\nOrchid: rejoining...") end)
        task.wait(0.5)
        TS:Teleport(game.PlaceId, player)
    else
        TS:TeleportToPlaceInstance(game.PlaceId, game.JobId, player)
    end
end
local function serverHop()
    local TS = game:GetService("TeleportService")
    notify("Server Hop", "Looking for another server...", 3)
    local ok, res = pcall(function()
        return HttpService:JSONDecode(game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100"))
    end)
    if not ok or type(res) ~= "table" or type(res.data) ~= "table" then notify("Server Hop", "Could not fetch the server list", 3, "danger"); return end
    local pick
    for _, sv in ipairs(res.data) do
        if sv.id ~= game.JobId and sv.playing and sv.maxPlayers and sv.playing < sv.maxPlayers - 1 then pick = sv; break end
    end
    if not pick then notify("Server Hop", "No other open server found", 3, "danger"); return end
    notify("Server Hop", "Joining a server with " .. tostring(pick.playing) .. " players", 3, "ok")
    task.wait(0.5)
    pcall(function() TS:TeleportToPlaceInstance(game.PlaceId, pick.id, player) end)
end
