local NB, gBars, gHist = 56, {}, {}
for i = 1, NB do
    gHist[i] = 0
    local bar = make("Frame", {BackgroundColor3 = T.AccentHi, BackgroundTransparency = 0.15 + 0.6 * (1 - i / NB), AnchorPoint = Vector2.new(0, 1),
    Position = UDim2.new((i - 1) / NB, 0, 1, 0), Size = UDim2.new(1 / NB, -2, 0, 2), BorderSizePixel = 0, ZIndex = 5}, gArea)
    gBars[i] = bar
end
onAccent(function() for _, b in ipairs(gBars) do b.BackgroundColor3 = T.AccentHi end end)
local function graphPush(v)
    for i = 1, NB - 1 do gHist[i] = gHist[i + 1] end
    gHist[NB] = v
    local sum, cnt = 0, 0
    for i = 1, NB do
        local h = gHist[i]
        if h > 0 then sum = sum + h; cnt = cnt + 1 end
        tween(gBars[i], 0.45, {Size = UDim2.new(1 / NB, -2, math.clamp(h / 144, 0.03, 1), 0)})
    end
    avgLbl.Text = "avg " .. (cnt > 0 and math.floor(sum / cnt + 0.5) or 0) .. " fps"
end

