CONFIG_VALUES["Cosmetics.Equipped"] = saved
local invertAll = CONFIG_VALUES["Cosmetics.Wraps.Options.Invert Patterns"] == true
local allWeapons = Cosmetic.Ready and Cosmetic.Weapons() or {}
local function viewportOf(holderF, model, outline)
local vp = make("ViewportFrame", {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = (outline == "black") and 5 or outline and 4 or 5,
Ambient = (outline == "black") and Color3.new(0, 0, 0) or outline and Color3.new(1, 1, 1) or Color3.fromRGB(190, 190, 200), LightColor = (outline == "black") and Color3.new(0, 0, 0) or Color3.new(1, 1, 1)}, holderF)
local ok = pcall(function()
if model:IsA("BasePart") then model.Anchored = true end
for _, d in ipairs(model:GetDescendants()) do
if d:IsA("BasePart") then d.Anchored = true end
end
model.Parent = vp
if outline then
for _, d in ipairs(model:GetDescendants()) do
if d:IsA("BasePart") then d.Color = (outline == "black") and Color3.new(0, 0, 0) or Color3.new(1, 1, 1); d.Material = (outline == "black") and Enum.Material.SmoothPlastic or Enum.Material.Neon; if d:IsA("MeshPart") then d.TextureID = "" end
elseif d:IsA("Decal") or d:IsA("Texture") or d:IsA("SurfaceAppearance") then d:Destroy() end
end
if model:IsA("BasePart") then model.Color = (outline == "black") and Color3.new(0, 0, 0) or Color3.new(1, 1, 1); model.Material = (outline == "black") and Enum.Material.SmoothPlastic or Enum.Material.Neon end
end
local cf, size
if model:IsA("Model") then cf, size = model:GetBoundingBox() else cf, size = model.CFrame, model.Size end
local cam = Instance.new("Camera")
cam.FieldOfView = 35
local dist = math.max(size.Magnitude, 0.5) * ((outline == "black") and 1.17 or outline and 1.03 or 1.25)
local dir = (cf.RightVector * 1.0 + cf.UpVector * 0.25 + cf.LookVector * 0.35).Unit
cam.CFrame = CFrame.lookAt(cf.Position + dir * dist, cf.Position)
cam.Parent = vp
vp.CurrentCamera = cam
end)
if not ok then vp:Destroy(); pcall(function() model:Destroy() end) end
return ok
end
local function cloneModel(src)
local model
pcall(function()
local arch = {}
local function unlock(i) if not i.Archivable then arch[#arch + 1] = i; i.Archivable = true end end
unlock(src); for _, d in ipairs(src:GetDescendants()) do unlock(d) end
if src:IsA("Folder") then
model = Instance.new("Model")
for _, ch in ipairs(src:GetChildren()) do
local cl = ch:Clone(); if cl then cl.Parent = model end
end
else
model = src:Clone()
end
for _, i in ipairs(arch) do i.Archivable = false end
end)
return model
end
local function iconView(holderF, model)
local g = make("ImageLabel", {BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = Color3.new(1, 1, 1), ImageTransparency = 0.45,
AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1.7, 1.7), ZIndex = 4}, holderF)
Anim.loop(g, "ImageTransparency", 0.3, 0.65, 1.2, true, Enum.EasingStyle.Sine)
viewportOf(holderF, model:Clone(), true)
viewportOf(holderF, model:Clone(), "black")
return viewportOf(holderF, model)
end
local RARN = {Color3.fromRGB(155, 155, 165), Color3.fromRGB(95, 205, 95), Color3.fromRGB(60, 145, 255), Color3.fromRGB(175, 85, 255), Color3.fromRGB(255, 170, 30), Color3.fromRGB(255, 60, 90), Color3.fromRGB(0, 230, 200)}
local RARS = {{"mythic", RARN[6]}, {"legend", RARN[5]}, {"exotic", RARN[7]}, {"immortal", RARN[7]}, {"epic", RARN[4]}, {"rare", RARN[3]}, {"uncommon", RARN[2]}, {"common", RARN[1]}}
local function rarColor(name)
local r = Cosmetic.Rarity and Cosmetic.Rarity(name)
if type(r) == "number" then return RARN[math.clamp(math.floor(r), 1, #RARN)] end
if r ~= nil then
local str = tostring(r):lower()
for _, p in ipairs(RARS) do if str:find(p[1], 1, true) then return p[2] end end
end
return RARN[1]
end
local NONE = "\1none"
local RAND = "\1rand"
local randSrc, randSearched
local function findRandomSrc()
if randSearched then return randSrc end
randSearched = true
pcall(function()
local function hit(x) x = tostring(x):lower(); return x:find("dice", 1, true) or x:find("random", 1, true) end
for _, w in ipairs(allWeapons) do
if hit(w) then randSrc = Cosmetic.WeaponModel(w); if randSrc then return end end
end
for _, w in ipairs(allWeapons) do
for _, sk in ipairs(Cosmetic.SkinsFor(w)) do
if hit(sk) then randSrc = Cosmetic.PreviewSource(sk); if randSrc then return end end
end
end
for _, n in ipairs(Cosmetic.Names("Charm")) do
if hit(n) then randSrc = Cosmetic.CharmModel(n); if randSrc then return end end
end
end)
return randSrc
end
