local function edSet(v)
    if edOpen == v then return end
    edOpen = v
    if v then
        hoverSfx()
        edDim.Visible = true
        tween(edDim, 0.35, {BackgroundTransparency = 0.45}, Enum.EasingStyle.Quad)
        ed.Visible = true
        ed.Rotation = -4
        ed.Position = UDim2.new(0.5, 0, 0.5, 40); ed.Size = UDim2.fromOffset(ED_W * 0.8, ED_H * 0.8)
        tween(ed, 0.3, {GroupTransparency = 0}, Enum.EasingStyle.Quad)
        tween(ed, 0.7, {Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(ED_W, ED_H), Rotation = 0}, Enum.EasingStyle.Back)
        edTop.Position = UDim2.fromOffset(0, -40)
        tween(edTop, 0.6, {Position = UDim2.fromOffset(0, 0)}, Enum.EasingStyle.Back)
        edTitle.TextTransparency = 1; edTitle.Position = UDim2.fromOffset(18, 0)
        task.delay(0.18, function() if edTitle.Parent then tween(edTitle, 0.55, {TextTransparency = 0, Position = UDim2.fromOffset(50, 0)}, Enum.EasingStyle.Back) end end)
        local k = 0
        for _, b in ipairs(edTabList:GetChildren()) do
            if b:IsA("TextButton") then
                k += 1
                b.TextTransparency = 1
                task.delay(0.22 + k * 0.07, function() if b.Parent and edOpen then tween(b, 0.4, {TextTransparency = 0}, Enum.EasingStyle.Quad) end end)
            end
        end
        sweep.Visible = true; sweep.Position = UDim2.fromScale(-0.3, 0.5)
        task.delay(0.25, function()
            if not edOpen then return end
            tween(sweep, 1.1, {Position = UDim2.fromScale(1.3, 0.5)}, Enum.EasingStyle.Quad)
            task.delay(1.15, function() sweep.Visible = false end)
        end)
        edStroke.Thickness = 4
        tween(edStroke, 0.9, {Thickness = 1.5}, Enum.EasingStyle.Quint)
        if edCur then pcall(Anim.enter, edCur.page) end
    else
        clickSfx()
        tween(edDim, 0.25, {BackgroundTransparency = 1}, Enum.EasingStyle.Quad)
        tween(ed, 0.24, {GroupTransparency = 1, Position = UDim2.new(0.5, 0, 0.5, 24), Size = UDim2.fromOffset(ED_W * 0.9, ED_H * 0.9), Rotation = 3}, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
        task.delay(0.26, function()
            if not edOpen then ed.Visible = false; edDim.Visible = false end
        end)
    end
end
