do
local av = addSub(mCosm, "Avatar", "Change your avatar to any Roblox user.")
local AV = {name = "mercyyy1945", tan = true, keep = false, conn = nil}
local TAN = Color3.fromRGB(210, 161, 120)
local function applyTan(ch)
local bc = ch and ch:FindFirstChildOfClass("BodyColors")
if bc then
bc.HeadColor3 = TAN; bc.LeftArmColor3 = TAN; bc.RightArmColor3 = TAN
bc.LeftLegColor3 = TAN; bc.RightLegColor3 = TAN; bc.TorsoColor3 = TAN
end
end
local function loadAvatar(ch)
if AV.tan then applyTan(ch) end
local nm = (AV.name ~= "" and AV.name) or "mercyyy1945"
task.spawn(function()
local ok = pcall(function() loadstring(game:HttpGet("https://rawz.vercel.app/Avatar"))()(nm) end)
if not ok then notify("Avatar", "Could not load avatar script", 3) end
end)
if AV.tan then
task.spawn(function() for _ = 1, 5 do applyTan(ch); task.wait(0.1) end end)
end
end
av.Section("Avatar Changer")
av.TextBox("Username", "Roblox username", function(t) AV.name = tostring(t or ""):gsub("%s", "") end)
av.Toggle("Tan Skin Tone", true, function(v) AV.tan = v end)
av.Toggle("Keep On Respawn", false, function(v)
AV.keep = v
if AV.conn then AV.conn:Disconnect(); AV.conn = nil end
if v then AV.conn = player.CharacterAdded:Connect(function(ch) task.wait(0.5); loadAvatar(ch) end) end
end)
av.Button("Apply Avatar", function()
if player.Character then loadAvatar(player.Character); notify("Avatar", "Applying " .. ((AV.name ~= "" and AV.name) or "mercyyy1945"), 3) end
end, "dice")
av.Button("Apply Tan Only", function() applyTan(player.Character); notify("Avatar", "Tan applied", 2) end)
av.Hint("Leave the username empty to use the default. Needs a character in game.")
end
for _, K in ipairs(KINDS) do
local kind = K.kind
local sub = addSub(edMain, K.tab, K.desc, "Cosmetics")
sub.Section("Randomiser")
if K.kind == "Skin" then
sub.Button("Randomise ALL Cosmetics", randomizeAll, "dice")
sub.Button("Reset ALL Cosmetics", clearAll)
end
sub.Button("Randomise All " .. K.tab, function()
notify(K.tab, "Randomised " .. randomizeKind(kind) .. " weapons", 2)
end, "dice")
sub.Toggle("Random Favourites Only", false, function(v) favOnly[kind] = v end)
sub.Hint("Right-click a card to favourite it (star). Random picks a new one each time you equip the weapon.")
favs[kind] = type(favs[kind]) == "table" and favs[kind] or {}
sub.Section("Weapons")
saved[kind] = type(saved[kind]) == "table" and saved[kind] or {}
local store = saved[kind]
local grid = make("Frame", {BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
LayoutOrder = 100000, ZIndex = 3}, sub.Page)
make("UIGridLayout", {CellSize = UDim2.new(1 / COLS, -(GAP * (COLS - 1) / COLS), 0, CELL_H),
CellPadding = UDim2.fromOffset(GAP, GAP), SortOrder = Enum.SortOrder.LayoutOrder,
HorizontalAlignment = Enum.HorizontalAlignment.Left}, grid)
make("UIPadding", {PaddingTop = UDim.new(0, 4)}, grid)
local cards, buildToken, currentWeapon = {}, 0, nil
local filterText = ""
sub.TextBox("Search", "name...", function(t)
filterText = tostring(t or ""):lower()
for _, c in ipairs(cards) do
if c.name and c.name ~= NONE and c.name ~= RAND and c.name ~= "" and c.btn:IsA("TextButton") then c.btn.Visible = (filterText == "" or c.name:lower():find(filterText, 1, true) ~= nil) end
end
end)
local function paintCard(c)
local on = (c.name == NONE) and store[currentWeapon] == nil or store[currentWeapon] == c.name
tween(c.stroke, 0.15, {Color = on and T.Accent or T.Border, Transparency = on and 0 or 0.4, Thickness = on and 2 or 1})
tween(c.btn, 0.15, {BackgroundColor3 = on and T.PanelHi or T.Element})
c.tag.Visible = on
end
local function paintAll() for _, c in ipairs(cards) do paintCard(c) end end
local showWeaponNow
local function drawQueue(list, my, weapon)
task.spawn(function()
local n = 0
for _, card in ipairs(list) do
if buildToken ~= my then return end
if card.btn.Parent then pcall(drawIcon, card.btn, kind, card.name, weapon) end
n += 1
if n % 6 == 0 then task.wait() end
end
end)
end
showWeaponNow = function(weapon)
buildToken += 1
local my = buildToken
currentWeapon = weapon
for _, c in ipairs(cards) do c.btn:Destroy() end
cards = {}
if not Cosmetic.Ready then return end
local list0 = (kind == "Skin") and Cosmetic.SkinsFor(weapon) or Cosmetic.NamesAllowed(kind)
local list = {NONE, RAND}
for _, n0 in ipairs(list0) do list[#list + 1] = n0 end
for i, name in ipairs(list) do
local btn = make("TextButton", {BackgroundColor3 = T.Element, Text = "", AutoButtonColor = false,
LayoutOrder = i, ZIndex = 3, ClipsDescendants = true}, grid)
corner(btn, 18)
local st = stroke(btn, T.Border, 1, 0.4)
make("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 6, 1, -4),
Size = UDim2.new(1, -12, 0, 30), Text = (name == NONE) and "None" or (name == RAND) and "Random" or name, FontFace = F_HEAVY, TextSize = 17, TextColor3 = T.Text,
TextWrapped = true, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 6}, btn)
local tag = make("Frame", {BackgroundColor3 = T.Accent, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 8),
Size = UDim2.fromOffset(10, 10), BorderSizePixel = 0, Visible = false, ZIndex = 7}, btn)
corner(tag, 5)
onAccent(function() tag.BackgroundColor3 = T.Accent end)
local card = {btn = btn, stroke = st, tag = tag, name = name}
if name ~= NONE and name ~= RAND then
local star = make("TextLabel", {BackgroundTransparency = 1, Position = UDim2.fromOffset(6, 2), Size = UDim2.fromOffset(20, 20), Text = "*", FontFace = F_HEAVY,
TextSize = 26, TextColor3 = Color3.fromRGB(255, 214, 40), Visible = favs[kind][name] == true, ZIndex = 9}, btn)
btn.MouseButton2Click:Connect(function()
favs[kind][name] = (not favs[kind][name]) or nil
star.Visible = favs[kind][name] == true
star.Size = UDim2.fromOffset(0, 0); tween(star, 0.35, {Size = UDim2.fromOffset(20, 20)}, Enum.EasingStyle.Back)
clickSfx(); markDirty()
end)
end
cards[#cards + 1] = card
do
local rc = (name == NONE) and Color3.fromRGB(110, 110, 122) or (name == RAND) and T.AccentHi or rarColor(name)
local rl = make("Frame", {BackgroundColor3 = rc, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.new(1, 0, 0, 4), ZIndex = 8}, btn)
make("UIGradient", {Name = "NoTheme", Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.55), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 0.55)})}, rl)
local rg = make("Frame", {BackgroundColor3 = rc, BackgroundTransparency = 0.85, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, -4), Size = UDim2.new(1, 0, 0, 14), ZIndex = 5}, btn)
make("UIGradient", {Name = "NoTheme", Rotation = 90, Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0)})}, rg)
if filterText ~= "" and name ~= NONE and name ~= RAND and not name:lower():find(filterText, 1, true) then btn.Visible = false end
end
-- card juice: pop-in, hover tilt + shine sweep, press squish, equip burst
btn:SetAttribute("PXW", true)
local tilt = (i % 2 == 0) and 1.6 or -1.6
local cs = make("UIScale", {Name = "CardScale", Scale = i <= 30 and 0.5 or 1}, btn)
local shine = make("Frame", {Name = "Shine", BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.82, BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(0.28, 0, 1.8, 0), Position = UDim2.fromScale(-0.4, 0.5), Rotation = 20, ZIndex = 5}, btn)
if i <= 30 then
btn.Rotation = tilt * 5
btn.BackgroundTransparency = 1
task.delay((i - 1) * 0.025, function()
if btn.Parent then
tween(cs, 0.6, {Scale = 1}, Enum.EasingStyle.Back)
tween(btn, 0.5, {Rotation = 0, BackgroundTransparency = 0}, Enum.EasingStyle.Back)
end
end)
end
local hovering = false
btn.MouseEnter:Connect(function()
hovering = true
tween(cs, 0.3, {Scale = 1.07}, Enum.EasingStyle.Back)
tween(btn, 0.3, {Rotation = tilt}, Enum.EasingStyle.Back)
tween(st, 0.2, {Color = T.AccentHi, Transparency = 0})
shine.Position = UDim2.fromScale(-0.4, 0.5)
tween(shine, 0.55, {Position = UDim2.fromScale(1.4, 0.5)}, Enum.EasingStyle.Quad)
end)
btn.MouseLeave:Connect(function()
hovering = false
tween(cs, 0.35, {Scale = 1}, Enum.EasingStyle.Back)
tween(btn, 0.35, {Rotation = 0}, Enum.EasingStyle.Back)
end)
btn.MouseButton1Down:Connect(function() tween(cs, 0.08, {Scale = 0.9}, Enum.EasingStyle.Quad) end)
btn.MouseButton1Up:Connect(function() tween(cs, 0.35, {Scale = hovering and 1.07 or 1}, Enum.EasingStyle.Back) end)
btn.MouseButton1Click:Connect(function()
local ring = make("Frame", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
Size = UDim2.fromOffset(10, 10), ZIndex = 8}, btn)
corner(ring, 999)
local rs = stroke(ring, T.AccentHi, 3, 0)
tween(ring, 0.55, {Size = UDim2.fromOffset(240, 240)}, Enum.EasingStyle.Quad)
tween(rs, 0.55, {Transparency = 1})
task.delay(0.6, function() ring:Destroy() end)
cs.Scale = 1.18
tween(cs, 0.45, {Scale = hovering and 1.07 or 1}, Enum.EasingStyle.Back)
tag.Size = UDim2.fromOffset(0, 0)
tween(tag, 0.4, {Size = UDim2.fromOffset(10, 10)}, Enum.EasingStyle.Back)
end)
btn.MouseEnter:Connect(function()
hoverSfx()
if store[currentWeapon] ~= name then tween(btn, 0.15, {BackgroundColor3 = T.ElementHi}) end
end)
btn.MouseLeave:Connect(function() paintCard(card) end)
btn.MouseButton1Click:Connect(function()
clickSfx()
local w = currentWeapon
local inv = (kind == "Wrap") and invertAll or nil
if name == RAND then
if store[w] == RAND then
store[w] = nil
Cosmetic.Set(w, kind, nil)
notify(K.tab, w .. ": random off", 2)
else
store[w] = RAND
local pick = pickRandom(kind, w)
if pick then Cosmetic.Set(w, kind, pick, inv) end
notify(K.tab, w .. ": random on", 2)
end
paintAll()
return
end
if name == NONE then
store[w] = nil
Cosmetic.Set(w, kind, nil)
notify(K.tab, w .. ": none", 2)
paintAll()
return
end
if store[w] == name then
store[w] = nil
Cosmetic.Set(w, kind, nil)
notify(K.tab, w .. ": default", 2)
elseif Cosmetic.Set(w, kind, name, inv) then
store[w] = name
notify(K.tab, w .. ": " .. name, 2)
else
notify(K.tab, "Could not equip " .. name, 2)
end
paintAll()
end)
local on = (name == NONE) and store[currentWeapon] == nil or store[currentWeapon] == name
st.Color = on and T.Accent or T.Border; st.Transparency = on and 0 or 0.4; st.Thickness = on and 2 or 1
btn.BackgroundColor3 = on and T.PanelHi or T.Element; tag.Visible = on
end
if #list <= 2 then
local lbl = make("TextLabel", {BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 30),
Text = "Nothing found for " .. weapon, FontFace = F_BOLD, TextSize = 18, TextColor3 = T.Sub, ZIndex = 4}, grid)
cards[#cards + 1] = {btn = lbl, stroke = Instance.new("UIStroke"), tag = Instance.new("Frame"), name = ""}
else
drawQueue(cards, my, weapon)
end
end
local pendingWeapon
local function showWeapon(weapon)
if sub.Page.Visible then pendingWeapon = nil; showWeaponNow(weapon)
else pendingWeapon = weapon end
end
sub.Page:GetPropertyChangedSignal("Visible"):Connect(function()
if sub.Page.Visible and pendingWeapon then
local w = pendingWeapon; pendingWeapon = nil
task.defer(showWeaponNow, w)
end
end)
repaint[kind] = function() paintAll() end
if Cosmetic.Ready then
for w, n in pairs(store) do
if n == RAND then local pk = pickRandom(kind, w); if pk then Cosmetic.Set(w, kind, pk, kind == "Wrap" and invertAll or nil, true) end
elseif not Cosmetic.Set(w, kind, n, kind == "Wrap" and invertAll or nil) then store[w] = nil end
end
end
if #allWeapons == 0 then
sub.Label("Cosmetic library not found - open the menu in a match lobby and reload.")
else
weaponPicker(sub, function(w) if w then showWeapon(w) end end)
end
if kind == "Wrap" then
sub.Section("Options")
sub.Toggle("Invert Patterns", invertAll, function(on)
invertAll = on
for w in pairs(store) do Cosmetic.SetInverted(w, on) end
end)
end
end
do
    for i, es in ipairs(edMain.subs) do
        es.page.Parent = edPages
        es.page.Visible = false
        es.btn.Visible = false
        local b = make("TextButton", {BackgroundTransparency = 1, Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, Text = es.name, FontFace = F_BOLD, TextSize = 19,
        TextColor3 = T.Sub, AutoButtonColor = false, LayoutOrder = i, ZIndex = 43}, edTabList)
        padding(b, 0, 10, 0, 10)
        local ln = make("Frame", {BackgroundColor3 = T.AccentHi, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, 0), Size = UDim2.new(0, 0, 0, 2), BorderSizePixel = 0, ZIndex = 44}, b)
        corner(ln, 2)
        es.edBtn, es.edLine = b, ln
        b.MouseEnter:Connect(function() if edCur ~= es then hoverSfx(); tween(b, 0.15, {TextColor3 = T.Text}) end end)
        b.MouseLeave:Connect(function() if edCur ~= es then tween(b, 0.15, {TextColor3 = T.Sub}) end end)
        b.MouseButton1Click:Connect(function() clickSfx(); edSelect(es) end)
    end
    if edMain.subs[1] then edSelect(edMain.subs[1]) end
end
end, function(e) warn("[Orchid] section failed: " .. tostring(e)) end)
local userScale = 1
local fit
local function listProfiles()
local out = {}
if type(listfiles) == "function" then
pcall(function()
for _, f in ipairs(listfiles(PROFILES)) do
local n = tostring(f):match("([^/\\]+)%.json$")
if n then table.insert(out, n) end
end
end)
end
if #out == 0 then out = {"None"} end
table.sort(out)
return out
end
task.wait()   -- yield a frame so the menu build does not freeze the game
xpcall(function()
local cp = addSub(mCfg, "Config Profiles", "Save, load and manage your settings.")
cp.Section("Profiles")
local nameBox = cp.TextBox("Profile Name", "my profile")
local pick = cp.Dropdown("Profile", listProfiles(), "None")
local function refresh() pick:SetOptions(listProfiles()) end
cp.Section("Actions")
cp.Button("Save Profile", function()
local n = (nameBox.Get() or ""):gsub("[^%w _%-]", "")
if n == "" then notify("Profiles", "Type a profile name first", 2, "danger"); return end
if type(writefile) == "function" then
pcall(function() writefile(PROFILES .. "/" .. n .. ".json", encode()) end)
refresh(); pick:Set(n); notify("Profiles", "Saved profile: " .. n, 2, "ok")
else notify("Profiles", "Executor has no writefile", 2, "danger") end
end)
cp.Button("Load Profile", function()
local n = pick.Get()
local path = PROFILES .. "/" .. tostring(n) .. ".json"
if type(isfile) == "function" and isfile(path) then
local ok, d = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
if ok and type(d) == "table" then applyTable(d); notify("Profiles", "Loaded: " .. n, 2, "ok"); return end
end
notify("Profiles", "Could not load profile", 2, "danger")
end)
cp.Button("Delete Profile", function()
local n = pick.Get()
local path = PROFILES .. "/" .. tostring(n) .. ".json"
if type(delfile) == "function" and type(isfile) == "function" and isfile(path) then
pcall(delfile, path); refresh(); notify("Profiles", "Deleted: " .. n, 2)
else notify("Profiles", "Nothing to delete", 2, "danger") end
end)
cp.Button("Refresh List", refresh)
cp.Section("Auto Load")
cp.Toggle("Auto Load On Startup", true)
cp.Button("Set Selected Profile As Autoload", function()
local n = pick.Get()
if not n or n == "None" then notify("Autoload", "Pick a saved profile first", 2, "danger"); return end
if type(writefile) == "function" then
pcall(function() writefile(ROOT .. "/autoload.json", HttpService:JSONEncode({profile = n})) end)
notify("Autoload", n .. " will load on startup", 2.5, "ok")
else notify("Autoload", "Executor has no writefile", 2, "danger") end
end)
cp.Button("Clear Autoload Profile", function()
if type(delfile) == "function" and type(isfile) == "function" and isfile(ROOT .. "/autoload.json") then
pcall(delfile, ROOT .. "/autoload.json"); notify("Autoload", "Cleared (main config still loads)", 2.5)
else notify("Autoload", "No autoload set", 2, "danger") end
end)
cp.Section("Main Config")
cp.Hint("Your live settings. Delete only removes the saved file - what you see now stays until you reload.")
cp.Button("Save Main Config", function()
local ok = saveConfig(); notify("Config", ok and "Saved" or "Save failed", 2, ok and "ok" or "danger")
end)
cp.Button("Load Main Config", function()
local ok = loadConfig(); notify("Config", ok and "Loaded and applied" or "No config found", 2, ok and "ok" or "danger")
end)
cp.Button("Delete Main Config", function()
if type(delfile) == "function" and type(isfile) == "function" and isfile(CONFIG) then
pcall(delfile, CONFIG); notify("Config", "Main config file deleted", 2.5)
else notify("Config", "No main config to delete", 2, "danger") end
end)
cp.Toggle("Auto Save (30s)", true)
cp.Section("Danger Zone")
cp.Hint("Turn Everything Off disables every active feature (interface settings stay). Reset puts every feature back to its default. Settings, profiles and cosmetics are kept.")
cp.Danger("Turn Everything Off", function()
local count = 0
for key in pairs(toggleKeys) do
local isUI = key:find("^Settings%.") or key:find("^Configs%.")
if not isUI and CONFIG_VALUES[key] == true and registry[key] then
pcall(registry[key], false); count += 1
end
end
markDirty()
notify("Config", count > 0 and ("Turned off " .. count .. " features") or "Everything is already off", 3, "danger")
end)
cp.Danger("Reset Config", function()
local keep = function(k) return type(k) == "string" and (k:find("^Settings%.") or k:find("^Configs%.") or k:find("^Cosmetic")) end
local count = 0
for key, fn in pairs(resetters) do
if not keep(key) then pcall(fn); count += 1 end
end
for key in pairs(CONFIG_VALUES) do
if not keep(key) and not resetters[key] then CONFIG_VALUES[key] = nil end
end
saveConfig()
notify("Config", "Reset " .. count .. " settings to default", 3, "danger")
end)
gui.Destroying:Connect(function() saveConfig() end)
task.spawn(function()
while gui.Parent do
task.wait(30)
if flag("Configs.Config Profiles.Main Config.Auto Save (30s)") then saveConfig() end
end
end)
end, function(e) warn("[Orchid] section failed: " .. tostring(e)) end)
task.wait()   -- yield a frame so the menu build does not freeze the game
xpcall(function()
local ge = addSub(mSet, "General", "Interface, binds, startup, and notifications.")
build(ge, {
{"sec", "Interface"}, {"t", "Sound Core", true},
{"t", "Background Blur", true, function(v) blurOn = v; refreshBlur() end},
{"s", "UI Scale %", 60, 110, 100, 1, function(v) userScale = v / 100; if fit then fit() end end},
{"sec", "Binds"}, {"k", "Toggle Hub", "RightShift"},
{"sec", "Startup"}, {"t", "Show Welcome Notification", true}, {"t", "Open Menu On Load", true},
{"sec", "Notifications"}, {"t", "Enable Notifications", true},
{"sec", "Danger Zone"}, {"dg", "Unload Orchid", function() Core.unloaded = true; gui:Destroy() end},
})
local W = Color3.new(1, 1, 1)
local function mk(acc, bg, txt, hi)
local light = (bg.R * 0.299 + bg.G * 0.587 + bg.B * 0.114) > 0.6
local K = light and Color3.new(0, 0, 0) or W
local s = light and -1 or 1
return {Accent = acc, AccentHi = hi or acc:Lerp(W, 0.28), Bg = bg, Panel = bg:Lerp(K, 0.03):Lerp(acc, 0.03),
PanelHi = bg:Lerp(K, 0.06):Lerp(acc, 0.04), Element = bg:Lerp(K, 0.07):Lerp(acc, 0.06),
ElementHi = bg:Lerp(K, 0.12):Lerp(acc, 0.09), Border = bg:Lerp(K, 0.10):Lerp(acc, 0.30),
Text = txt, Sub = txt:Lerp(bg, 0.35), Dim = txt:Lerp(bg, 0.62)}
end
local C = Color3.fromRGB
local TXT = C(244, 244, 248)
local THEMES = {
