{"sec", "Custom Accent"},
{"cw", "Accent Colour", "#FFBE14", wheelTo("AR", "AG", "AB", 0, 1)},
{"sec", "Custom Background"},
{"cw", "Background Colour", "#0C0903", wheelTo("BR", "BG", "BB", 0, 0.27)},
{"sec", "Custom Text"},
