xpcall(function()
local fs = addSub(mCosm, "Fonts", "Change the font on every UI: this hub, the game UI and other scripts' UIs.", "Visual")
local t0 = os.clock()
local CATS = {"Thin & Light", "Regular", "Medium & Semibold", "Bold & Heavy", "Plump & Chunky", "Condensed", "Serif",
"Mono & Code", "Handwritten & Script", "Fancy & Display", "Sci-Fi & Pixel", "Italic", "Other"}
local lists, seen = {}, {}
for _, c in ipairs(CATS) do lists[c] = {} end
local function addFont(cat, label, font)
local key = cat .. "|" .. label
if seen[key] or not lists[cat] then return end
seen[key] = true
table.insert(lists[cat], {label = label, font = font})
end
-- every Roblox font enum, sorted into groups (anything new Roblox adds lands in "Other")
local EC = {
Legacy = {"Regular"}, Arial = {"Regular"}, ArialBold = {"Bold & Heavy"}, SourceSans = {"Regular"},
SourceSansBold = {"Bold & Heavy"}, SourceSansSemibold = {"Medium & Semibold"}, SourceSansLight = {"Thin & Light"},
SourceSansItalic = {"Italic"}, Bodoni = {"Serif"}, Garamond = {"Serif"}, Cartoon = {"Plump & Chunky", "Fancy & Display"},
Code = {"Mono & Code"}, Highway = {"Regular"}, SciFi = {"Sci-Fi & Pixel"}, Arcade = {"Sci-Fi & Pixel"},
Fantasy = {"Fancy & Display"}, Antique = {"Serif", "Fancy & Display"}, Gotham = {"Regular"},
GothamMedium = {"Medium & Semibold"}, GothamSemibold = {"Medium & Semibold"}, GothamBold = {"Bold & Heavy"},
GothamBlack = {"Bold & Heavy", "Plump & Chunky"}, AmaticSC = {"Condensed", "Handwritten & Script"},
Bangers = {"Plump & Chunky", "Fancy & Display"}, Creepster = {"Fancy & Display"}, DenkOne = {"Plump & Chunky"},
Fondamento = {"Handwritten & Script", "Serif"}, FredokaOne = {"Plump & Chunky"}, GrenzeGotisch = {"Fancy & Display"},
IndieFlower = {"Handwritten & Script"}, JosefinSans = {"Regular", "Thin & Light"}, Jura = {"Sci-Fi & Pixel", "Regular"},
Kalam = {"Handwritten & Script"}, LuckiestGuy = {"Plump & Chunky"}, Merriweather = {"Serif"},
Michroma = {"Sci-Fi & Pixel", "Bold & Heavy"}, Nunito = {"Regular"}, Oswald = {"Condensed", "Bold & Heavy"},
PatrickHand = {"Handwritten & Script"}, PermanentMarker = {"Handwritten & Script", "Bold & Heavy"},
Roboto = {"Regular"}, RobotoCondensed = {"Condensed"}, RobotoMono = {"Mono & Code"}, Sarpanch = {"Sci-Fi & Pixel", "Condensed"},
SpecialElite = {"Handwritten & Script", "Fancy & Display"}, TitilliumWeb = {"Regular"}, Ubuntu = {"Regular"},
BuilderSans = {"Regular"}, BuilderSansMedium = {"Medium & Semibold"}, BuilderSansBold = {"Bold & Heavy"},
BuilderSansExtraBold = {"Bold & Heavy", "Plump & Chunky"}, Arimo = {"Regular"}, ArimoBold = {"Bold & Heavy"},
}
for _, item in ipairs(Enum.Font:GetEnumItems()) do
if item.Name ~= "Unknown" then
local ok, f = pcall(Font.fromEnum, item)
if ok and f then
local label = (item.Name:gsub("(%l)(%u)", "%1 %2"))
for _, c in ipairs(EC[item.Name] or {"Other"}) do addFont(c, label, f) end
end
end
end
-- full weight ladders for the families that have them
local WCAT = {Thin = {"Thin & Light"}, ExtraLight = {"Thin & Light"}, Light = {"Thin & Light"}, Regular = {"Regular"},
Medium = {"Medium & Semibold"}, SemiBold = {"Medium & Semibold"}, Bold = {"Bold & Heavy"},
ExtraBold = {"Bold & Heavy"}, Heavy = {"Bold & Heavy", "Plump & Chunky"}}
local FAMS = {
{"Montserrat", "Montserrat", {"Thin", "ExtraLight", "Light", "Regular", "Medium", "SemiBold", "Bold", "ExtraBold", "Heavy"}},
{"Source Sans Pro", "SourceSansPro", {"ExtraLight", "Light", "Regular", "SemiBold", "Bold", "Heavy"}},
{"Nunito", "Nunito", {"ExtraLight", "Light", "Regular", "SemiBold", "Bold", "ExtraBold", "Heavy"}},
{"Roboto", "Roboto", {"Thin", "Light", "Regular", "Medium", "Bold", "Heavy"}},
{"Oswald", "Oswald", {"ExtraLight", "Light", "Regular", "Medium", "SemiBold", "Bold"}},
{"Josefin Sans", "JosefinSans", {"Thin", "ExtraLight", "Light", "Regular", "Medium", "SemiBold", "Bold"}},
{"Titillium Web", "TitilliumWeb", {"ExtraLight", "Light", "Regular", "SemiBold", "Bold", "Heavy"}},
{"Ubuntu", "Ubuntu", {"Light", "Regular", "Medium", "Bold"}},
{"Gotham", "GothamSSm", {"Light", "Regular", "Medium", "Bold", "Heavy"}},
{"Builder Sans", "BuilderSans", {"Regular", "Medium", "Bold", "ExtraBold"}},
{"Merriweather", "Merriweather", {"Light", "Regular", "Bold", "Heavy"}},
}
for _, fam in ipairs(FAMS) do
for _, wn in ipairs(fam[3]) do
local okw, w = pcall(function() return Enum.FontWeight[wn] end)
if okw and w then
local ok, f = pcall(Font.fromName, fam[2], w, Enum.FontStyle.Normal)
if ok and f then
local cats = WCAT[wn]
if fam[1] == "Merriweather" then cats = {wn == "Regular" and "Serif" or cats[1], "Serif"} end
for _, c in ipairs(cats) do addFont(c, fam[1] .. " " .. wn, f) end
end
end
end
end
local FS = {orig = setmetatable({}, {__mode = "k"}), font = nil, cat = nil, gen = 0, hub = true, core = true, keepW = false, conns = {}}
local TEXTC = {TextLabel = true, TextButton = true, TextBox = true}
local function target(inst)
local ok, cur = pcall(function() return inst.FontFace end)
if not ok or not FS.font then return end
if FS.orig[inst] == nil then FS.orig[inst] = cur end
local f = FS.font
if FS.keepW then
local o = FS.orig[inst]
local ok2, nf = pcall(Font.new, f.Family, o.Weight, o.Style)
if ok2 then f = nf end
end
pcall(function() inst.FontFace = f end)
end
local function wanted(d)
return TEXTC[d.ClassName] and (FS.hub or not d:IsDescendantOf(gui))
end
local function roots()
local r = {PG}
if FS.core then
local hg
pcall(function() if gethui then hg = gethui() end end)
if hg and hg ~= PG then r[#r + 1] = hg end
pcall(function() r[#r + 1] = game:GetService("CoreGui") end)
end
return r
end
local function watch()
for _, c in ipairs(FS.conns) do pcall(function() c:Disconnect() end) end
FS.conns = {}
for _, root in ipairs(roots()) do
pcall(function()
table.insert(FS.conns, root.DescendantAdded:Connect(function(d)
if FS.font and wanted(d) then
task.defer(target, d)
task.delay(0.2, target, d)   -- scripts often set their own font right after parenting
end
end))
end)
end
end
local function sweepAll(my)
local n = 0
for _, root in ipairs(roots()) do
local ok, list = pcall(function() return root:GetDescendants() end)
if ok then
for i = 1, #list do
if FS.gen ~= my then return end
local d = list[i]
if wanted(d) then target(d) end
n += 1
if n % 400 == 0 then task.wait() end
end
end
end
end
local function applyFont(font)
FS.gen += 1
FS.font = font
watch()
task.spawn(sweepAll, FS.gen)
end
local function restoreAll()
FS.gen += 1
FS.font = nil
for _, c in ipairs(FS.conns) do pcall(function() c:Disconnect() end) end
FS.conns = {}
local old = FS.orig
FS.orig = setmetatable({}, {__mode = "k"})
local n = 0
for inst, o in pairs(old) do
if inst.Parent then pcall(function() inst.FontFace = o end) end
n += 1
if n % 400 == 0 then task.wait() end
end
end
local function reapply()
local f = FS.font
if not f then return end
task.spawn(function() restoreAll(); FS.font = f; applyFont(f) end)
end
local dds, byLabel = {}, {}
local function onPick(cat, v)
if v == "Default" then
if FS.cat == cat then FS.cat = nil; task.spawn(restoreAll) end
return
end
local entry = byLabel[cat] and byLabel[cat][v]
if not entry then return end
FS.cat = cat
for c, dd in pairs(dds) do
if c ~= cat and dd:Get() ~= "Default" then dd:Set("Default") end
end
applyFont(entry)
if os.clock() - t0 > 8 then notify("Fonts", v .. " applied to every UI", 2) end
end
fs.Section("Options")
fs.Toggle("Keep Bold / Regular Weights", false, function(v) FS.keepW = v; reapply() end)
fs.Toggle("Include This Hub", true, function(v) FS.hub = v; reapply() end)
fs.Toggle("Include CoreGui / Hidden UIs", true, function(v) FS.core = v; reapply() end)
fs.Label("Pick a font in ANY group below. It is applied to this hub, the game UI and UIs made by other scripts, including ones that open later.")
fs.Button("Reset All Fonts", function()
for _, dd in pairs(dds) do if dd:Get() ~= "Default" then dd:Set("Default") end end
FS.cat = nil
task.spawn(restoreAll)
end)
for _, cat in ipairs(CATS) do
local list = lists[cat]
if #list > 0 then
table.sort(list, function(a, b) return a.label < b.label end)
local opts, map = {"Default"}, {}
for _, e in ipairs(list) do opts[#opts + 1] = e.label; map[e.label] = e.font end
byLabel[cat] = map
fs.Section(cat)
dds[cat] = fs.Dropdown(cat, opts, "Default", function(v) onPick(cat, v) end)
end
end
gui.Destroying:Connect(function() pcall(restoreAll) end)
end, function(e) warn("[Orchid] Fonts tab failed to build: " .. tostring(e)) end)
task.wait()
task.wait()   -- yield a frame so the menu build does not freeze the game
do
local op = addSub(mSet, "Optimisation", "Hide everything outside your view in first person.")
local OPT = {on = false, fov = 140}
local MAXFOV = 140
local partSet, fxSet, fxOwner = {}, {}, {}
local hiddenParts, hiddenFx, ignored = {}, {}, {}
local conns, active, bound = {}, false, false
local BIND = "OrchidOptimise"
local function fxProp(i)
if i:IsA("Decal") then return "Transparency" end
if i:IsA("ParticleEmitter") or i:IsA("Beam") or i:IsA("Trail") or i:IsA("Fire") or i:IsA("Smoke")
or i:IsA("Sparkles") or i:IsA("Light") or i:IsA("Highlight") or i:IsA("BillboardGui") or i:IsA("SurfaceGui") then
return "Enabled"
end
end
local function ownerOf(i)
local p = i:FindFirstAncestorWhichIsA("BasePart")
if p then return p end
local par = i.Parent
if par and par:IsA("Model") then return par.PrimaryPart or par:FindFirstChildWhichIsA("BasePart", true) end
if i:IsA("Highlight") and i.Adornee then
local a = i.Adornee
if a:IsA("BasePart") then return a end
return a:FindFirstChildWhichIsA("BasePart", true)
end
end
local function trackInst(i)
if i:IsA("BasePart") then
if i:IsA("Terrain") then return end
local c = workspace.CurrentCamera
if c and i:IsDescendantOf(c) then return end
partSet[i] = true
elseif fxProp(i) then
local c = workspace.CurrentCamera
if c and i:IsDescendantOf(c) then return end
fxSet[i] = true; fxOwner[i] = ownerOf(i)
end
end
local function untrack(i)
partSet[i] = nil; hiddenParts[i] = nil; ignored[i] = nil
fxSet[i] = nil; fxOwner[i] = nil; hiddenFx[i] = nil
end
local function restoreAll()
for p, orig in pairs(hiddenParts) do
pcall(function() p.LocalTransparencyModifier = orig end)
end
for i, st in pairs(hiddenFx) do
pcall(function() i[st[1]] = st[2] end)
end
hiddenParts, hiddenFx = {}, {}
active = false
end
local function firstPerson(c)
if player.CameraMode == Enum.CameraMode.LockFirstPerson then return true end
local char = player.Character
local head = char and char:FindFirstChild("Head")
if head and head:IsA("BasePart") then
return (c.CFrame.Position - head.Position).Magnitude < 1.6
end
return false
end
local function step()
local c = workspace.CurrentCamera
if not c or not firstPerson(c) then
if active then restoreAll() end
return
end
active = true
local cf = c.CFrame
local cp, look = cf.Position, cf.LookVector
local half = math.rad(math.clamp(OPT.fov, 20, MAXFOV) / 2)
local cosH, sinH = math.cos(half), math.sin(half)
local char = player.Character
for p in pairs(partSet) do
local d = p.Position - cp
local dist = d.Magnitude
local rad = p.Size.Magnitude * 0.5
local cull = false
if dist > rad + 1 then
local s = rad / dist
local cosM = math.sqrt(1 - s * s)
local limit = cosH * cosM - sinH * s   -- cos(half + margin)
cull = (d:Dot(look) / dist) < limit
end
local was = hiddenParts[p] ~= nil
if cull and not was then
if ignored[p] or (char and p:IsDescendantOf(char)) then
ignored[p] = true
else
hiddenParts[p] = p.LocalTransparencyModifier
p.LocalTransparencyModifier = 1
end
elseif was and not cull then
p.LocalTransparencyModifier = hiddenParts[p]
hiddenParts[p] = nil
end
end
for i in pairs(fxSet) do
local o = fxOwner[i]
if o and not partSet[o] then o = nil end
local hide = o ~= nil and hiddenParts[o] ~= nil
local st = hiddenFx[i]
if hide and not st then
local prop = fxProp(i)
hiddenFx[i] = {prop, i[prop]}
i[prop] = (prop == "Transparency") and 1 or false
elseif st and not hide then
i[st[1]] = st[2]
hiddenFx[i] = nil
end
end
end
local function start()
if bound then return end
bound = true
for _, i in ipairs(workspace:GetDescendants()) do trackInst(i) end
conns[1] = workspace.DescendantAdded:Connect(trackInst)
conns[2] = workspace.DescendantRemoving:Connect(untrack)
RunService:BindToRenderStep(BIND, Enum.RenderPriority.Camera.Value + 3, function() pcall(step) end)
pcall(step)
end
local function stop()
if not bound then return end
bound = false
pcall(function() RunService:UnbindFromRenderStep(BIND) end)
for _, cn in ipairs(conns) do cn:Disconnect() end
conns = {}
restoreAll()
partSet, fxSet, fxOwner, ignored = {}, {}, {}, {}
end
op.Section("View Culling")
op.Toggle("Optimisation", false, function(v)
OPT.on = v
if v then start() else stop() end
end)
op.Slider("Culling FOV", 60, MAXFOV, 140, function(v)
OPT.fov = math.min(v, MAXFOV)
if bound then pcall(step) end
end, 1)
op.Hint("In first person, everything outside this view cone (max 140) is hidden: parts, meshes, decals, textures, players and effects. Updates every frame and restores instantly when turned off or when you leave first person.")
gui.Destroying:Connect(stop)
end
end, function(e) warn("[Orchid] section failed: " .. tostring(e)) end)
