refreshBlur = function() tween(blurFx, 0.35, {Size = (isOpen and blurOn) and 8 or 0}) end
local function setOpen(v)
if isOpen == v then return end
isOpen = v; token += 1
refreshBlur()
local my = token
if v then
win.Visible = true; shadow.Visible = true
win.Rotation = 0
win.Position = UDim2.fromScale(0.5, 0.5)
local intro = firstOpen; firstOpen = false
if not intro then
-- re-open: no show at all, just a tiny fade so it does not pop
winScale.Scale = 1
win.GroupTransparency = 0.6
tween(win, 0.1, {GroupTransparency = 0}, Enum.EasingStyle.Linear)
tween(shadow, 0.12, {ImageTransparency = 0.55})
else
-- first execute: window rises + settles, light sweeps across, tab names bounce in from the left
winScale.Scale = 0.9
win.GroupTransparency = 1
win.Position = UDim2.new(0.5, 0, 0.5, 34)
tween(win, 0.5, {GroupTransparency = 0}, Enum.EasingStyle.Quad)
tween(win, 0.75, {Position = UDim2.fromScale(0.5, 0.5)}, Enum.EasingStyle.Quint)
tween(winScale, 0.8, {Scale = 1}, Enum.EasingStyle.Back)
tween(shadow, 0.7, {ImageTransparency = 0.55})
sweep.Visible = true; sweep.Position = UDim2.fromOffset(-120, 0)
tween(sweep, 0.9, {Position = UDim2.fromOffset(WIN_W + 20, 0)}, Enum.EasingStyle.Quint).Completed:Connect(function() sweep.Visible = false end)
for idx, m in ipairs(mains) do   -- sidebar tab names: left -> right, bouncy
if m.item.Visible and m.itemLbl then
local lx = (activeMain == m) and 23 or 18
m.itemLbl.Position = UDim2.fromOffset(-170, 0)
m.itemLbl.TextTransparency = 1
task.delay(0.2 + (idx - 1) * 0.065, function()
if m.itemLbl.Parent then
tween(m.itemLbl, 0.85, {Position = UDim2.fromOffset(lx, 0)}, Enum.EasingStyle.Bounce)
tween(m.itemLbl, 0.3, {TextTransparency = 0}, Enum.EasingStyle.Quad)
end
end)
end
end
if activeMain and activeMain.bar then   -- the sub tabs bounce in too
local sc = activeMain.bar.scroll
sc.Position = UDim2.fromOffset(-260, 4)
task.delay(0.35, function()
if sc.Parent then tween(sc, 0.9, {Position = UDim2.fromOffset(10, 4)}, Enum.EasingStyle.Bounce) end
end)
end
if activeSub then Anim.enter(activeSub.page) end
end
else
tween(winScale, 0.12, {Scale = 0.97}, Enum.EasingStyle.Quad)
tween(shadow, 0.12, {ImageTransparency = 1})
tween(win, 0.12, {GroupTransparency = 1}, Enum.EasingStyle.Quad).Completed:Connect(function()
if token == my and not isOpen then win.Visible = false; shadow.Visible = false end
end)
end
end
