end
local function watchCam(cam)
if camConn then camConn:Disconnect() end
if not cam then return end
camConn = cam:GetPropertyChangedSignal("CameraType"):Connect(function()
if cam.CameraType == Enum.CameraType.Scriptable then wasOpen = isOpen
else task.delay(0.1, showHub); task.delay(1, showHub) end
end)
end
watchCam(workspace.CurrentCamera)
track(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function() watchCam(workspace.CurrentCamera); task.delay(0.2, showHub) end))
